const memUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024, files: 1 },
  fileFilter: (req, file, cb) => {
    const allowedMimes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    const ok = allowedMimes.includes(file.mimetype);
    const allowedExt = [".jpg", ".jpeg", ".png", ".webp"];
    const ext = path.extname(file.originalname).toLowerCase();
    return ok && allowedExt.includes(ext)
      ? cb(null, true)
      : cb(new Error("Formato não permitido"));
  },
});

const uploadExcel = multer({
  storage: multer.memoryStorage(), // ✅ mais simples pra Excel
  limits: { fileSize: 20 * 1024 * 1024 }, // 20MB
  fileFilter: (req, file, cb) => {
    const ok =
      file.mimetype ===
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" || // xlsx
      file.mimetype === "application/vnd.ms-excel" || // xls
      file.originalname.endsWith(".xlsx") ||
      file.originalname.endsWith(".xls");

    if (!ok)
      return cb(new Error("Apenas arquivos Excel (.xlsx/.xls) são permitidos"));
    cb(null, true);
  },
});

function getTwilioClient() {
  if (twilioClient) return twilioClient;

  if (twilioInitError) throw new Error(twilioInitError);

  if (!process.env.TWILIO_ACCOUNT_SID || !process.env.TWILIO_AUTH_TOKEN) {
    twilioInitError =
      "TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN environment variables are required for SMS functionality";
    throw new Error(twilioInitError);
  }

  if (!process.env.TWILIO_ACCOUNT_SID.startsWith("AC")) {
    twilioInitError = 'TWILIO_ACCOUNT_SID must start with "AC"';
    throw new Error(twilioInitError);
  }

  try {
    // console.log(`🔐 [TWILIO] Inicializando com SID: ${process.env.TWILIO_ACCOUNT_SID?.substring(0, 8)}...`);
    // console.log(`🔐 [TWILIO] Token length: ${process.env.TWILIO_AUTH_TOKEN?.length} caracteres`);

    twilioClient = twilio(
      process.env.TWILIO_ACCOUNT_SID,
      process.env.TWILIO_AUTH_TOKEN
    );
    return twilioClient;
  } catch (error: any) {
    twilioInitError = `Failed to initialize Twilio: ${error.message}`;
    throw new Error(twilioInitError);
  }
}

