// Magic numbers para validação de imagens
const IMAGE_MAGIC_NUMBERS = {
  jpg: [0xff, 0xd8, 0xff],
  jpeg: [0xff, 0xd8, 0xff],
  png: [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a],
  webp: [0x52, 0x49, 0x46, 0x46],
};

// Função para validar magic number de imagem
function validateImageMagicNumber(buffer: Buffer): boolean {
  for (const [format, signature] of Object.entries(IMAGE_MAGIC_NUMBERS)) {
    if (signature.every((byte, index) => buffer[index] === byte)) {
      return true;
    }
  }
  return false;
}

// Middleware para verificar autenticação obrigatória
async function requireAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    // 🔒 PRIORIDADE 0: Dev mode — bypass RBAC completamente
    const devAccessQuery = req.query.dev_access === "true";
    const devAccessHeader = req.headers["x-dev-access"] === "true";
    const devReferer =
      req.headers.referer?.includes("dev_access=true") ||
      req.headers.referer?.includes("/dev");
    const isDevMode =
      isDevRequest(req) || devAccessQuery || devAccessHeader || devReferer;

    if (isDevMode) {
      const devUser: any = { id: 1, nome: 'Dev User', papel: 'dev' };
      const urlMatch = req.path.match(/\/api\/monitor\/([0-9]+)/);
      const headerUserId = req.headers["x-user-id"];
      const targetId = urlMatch ? parseInt(urlMatch[1]) : (headerUserId ? parseInt(String(headerUserId)) : null);
      if (targetId && !isNaN(targetId)) {
        try {
          const targetUser = await db.select().from(users).where(eq(users.id, targetId)).limit(1);
          if (targetUser?.length) {
            devUser.id = targetId;
            devUser.email = targetUser[0].email;
            devUser.nome = targetUser[0].nome || 'Dev User';
          }
          if (!devUser.email || devUser.id === 1) {
            const monitorRow = await db.select().from(monitores).where(eq(monitores.id, targetId)).limit(1);
            if (monitorRow?.length) {
              devUser.email = monitorRow[0].email;
              devUser.monitorId = monitorRow[0].id;
            }
          }
        } catch (e) { /* silently continue */ }
      }
      (req as any).user = devUser;
      (req as any).isDeveloper = true;
      return next();
    }

    // 🔒 PRIORIDADE 1: x-user-id header presente — autenticação direta (monitor/professor)
    // Tem prioridade sobre sessão de coordenador para evitar conflito em máquina compartilhada
    const xUserIdHeader = req.headers["x-user-id"];
    if (xUserIdHeader) {
      const xUserIdNum = parseInt(String(xUserIdHeader), 10);
      if (!isNaN(xUserIdNum)) {
        const userByHeader = await storage.getUser(xUserIdNum);
        if (userByHeader) {
          (req as any).user = userByHeader;
          return next();
        }
        // Se não encontrou como usuário, tenta como coordenador pelo header
        const coordByHeader = await db.select().from(coordenadores).where(eq(coordenadores.id, xUserIdNum)).limit(1);
        if (coordByHeader && coordByHeader.length > 0) {
          const coord = coordByHeader[0];
          const coordinatorRoleMap: Record<string, string> = {
            psicossocial: "coordenador_psico",
            esporte_cultura: "coordenador_pec",
            inclusao_produtiva: "coordenador_inclusao",
          };
          const papel = coordinatorRoleMap[coord.setor] ?? "coordenador";
          (req as any).user = { id: xUserIdNum, papel, role: papel, email: coord.email, nome: coord.nome };
          return next();
        }
        return res.status(401).json({ error: "Usuário não encontrado" });
      }
    }

    // 🔒 PRIORIDADE 2: Sessão de coordenador (sem x-user-id)
    const session = req.session as any;
    if (session?.isCoordinator && session?.coordenadorId) {
      const coordId = session.coordenadorId;
      const coordenador = await db
        .select()
        .from(coordenadores)
        .where(eq(coordenadores.id, coordId))
        .limit(1);

      if (coordenador && coordenador.length > 0) {
        (req as any).coordenador = coordenador[0];
        (req as any).user = {
          id: coordId,
          papel: session.userPapel || "coordenador",
          role: session.userPapel || "coordenador",
          email: session.coordenadorEmail || session.userEmail || coordenador[0].email,
          nome: session.coordenadorNome || session.userName || coordenador[0].nome,
          actorType: "coordenador",
        };
        return next();
      }
    }

    return res.status(401).json({
      error: "Autenticação obrigatória - cabeçalho x-user-id necessário",
    });
  } catch (error) {
    console.error("Erro no middleware de autenticação:", error);
    res.status(500).json({ error: "Erro interno do servidor" });
  }
}

// Middleware para verificar autenticação de desenvolvedor
async function requireDevAuth(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    console.log("[requireDevAuth] Session data:", {
      hasSession: !!req.session,
      developerId: req.session?.developerId,
      userPapel: req.session?.userPapel,
      sessionID: req.sessionID,
    });

    const developerId = req.session?.developerId;
    const userPapel = req.session?.userPapel;

    if (
      !developerId ||
      (userPapel !== "dev" && userPapel !== "desenvolvedor")
    ) {
      console.log("[requireDevAuth] Auth failed - missing session data");
      return res
        .status(401)
        .json({ error: "Acesso negado - sessão de desenvolvedor requerida" });
    }

    // Anexar info do desenvolvedor ao request
    (req as any).developerId = developerId;
    console.log("[requireDevAuth] Auth successful for developer:", developerId);
    return next();
  } catch (error) {
    console.error("[requireDevAuth] Error:", error);
    return res.status(500).json({ error: "Erro ao verificar autenticação" });
  }
}

// Middleware para verificar se usuário é admin
function requireAdmin(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  const user = (req as any).user;
  if (!user) {
    return res.status(401).json({ error: "Usuário não autenticado" });
  }

  const isAdmin =
    isAdminEmail(user.email) || user.role === "admin" || user.tipo === "admin";
  if (!isAdmin) {
    console.warn(
      `🚨 [SECURITY] Tentativa de acesso admin negada - Usuário ${user.id} (${user.email})`
    );
    return res.status(403).json({
      error: "Acesso negado - privilégios administrativos necessários",
    });
  }

  console.log(`✅ [ADMIN ACCESS] Admin ${user.id} (${user.email}) autorizado`);
  next();
}

// ================ RBAC MIDDLEWARE SYSTEM ================
// Middleware para verificação de papéis específicos RBAC
function requireRole(allowedRoles: string[]) {
  return (
    req: express.Request,
    res: express.Response,
    next: express.NextFunction
  ) => {
    const user = (req as any).user;
    if (!user) {
      return res.status(401).json({ error: "Usuário não autenticado" });
    }

    // Obter papel do usuário (compatibilidade com campos existentes)
    const userRole = user.papel || user.userPapel || user.tipo || user.role;

    // PERMITIR ACESSO EM DEV MODE (bypass RBAC)
    if (userRole === "dev") {
      console.log(
        `✅ [DEV MODE] Usuário ${user.id} acessando com papel "dev" (RBAC bypass)`
      );
      next();
      return;
    }

    // Verificar se o papel do usuário está na lista de papéis permitidos
    if (!userRole || !allowedRoles.includes(userRole)) {
      console.warn(
        `🚨 [RBAC] Acesso negado - Usuário ${user.id} (${
          user.email
        }) papel "${userRole}" não autorizado. Papéis permitidos: ${allowedRoles.join(
          ", "
        )}`
      );
      return res.status(403).json({
        error: "Acesso negado - papel insuficiente",
        details: `Papel "${userRole}" não autorizado para este recurso`,
      });
    }

    console.log(`✅ [RBAC] Usuário ${user.id} papel "${userRole}" autorizado`);
    next();
  };
}

// Helper para verificar acesso a recursos próprios com bypass dev mode
function ensureSelfAccess(
  user: any,
  targetId: number,
  resourceName: string = "recurso"
): { allowed: boolean; error?: any } {
  const userRole = user.papel || user.userPapel || user.tipo || user.role;
  if (userRole === "dev") {
    return { allowed: true };
  }

  if (user.id !== targetId) {
    console.warn(
      `🚨 [SECURITY] User ${user.id} tentou acessar ${resourceName} de user ${targetId}`
    );
    return {
      allowed: false,
      error: {
        status: 403,
        message: `Acesso negado - você só pode acessar seu próprio ${resourceName}`,
      },
    };
  }

  return { allowed: true };
}

// Middleware específicos para cada papel RBAC
const requireProfessor = requireRole(['professor']);
const requireMonitor = requireRole(['monitor', 'monitor_pec', 'monitor_inclusao', 'monitor_psico']);
const requireCoordenadorInclusao = requireRole(['coordenador_inclusao']);
const requireCoordenadorPEC = requireRole(['coordenador_pec']);
const requireCoordenadorPsico = requireRole(['coordenador_psico', 'coordenador', 'monitor_psico']);
const requireAnyCoordenador = requireRole(['coordenador_inclusao', 'coordenador_pec', 'coordenador_psico']);

// Middleware para verificar múltiplos papéis (permite qualquer um da lista)
function requireAnyRole(allowedRoles: string[]) {
  return requireRole(allowedRoles);
}

// Middleware para validação de imagem com magic number
// TRECHO ALTERADO
// ✅ Versão compatível com memoryStorage
function validateImageFile(
  req: express.Request,
  res: express.Response,
  next: express.NextFunction
) {
  try {
    const f = req.file;

    if (!f) {
      return res.status(400).json({ error: "Nenhum arquivo foi enviado" });
    }

    // ✅ diskStorage: valida usando o arquivo salvo em disco
    if (!f.path) {
      return res.status(400).json({ error: "Arquivo inválido (sem caminho no disco)" });
    }

    // lê o arquivo real
    const buf = fs.readFileSync(f.path);

    if (!buf || buf.length === 0) {
      return res.status(400).json({ error: "Arquivo inválido ou vazio" });
    }

    // 1) magic number
    if (!validateImageMagicNumber(buf)) {
      return res.status(400).json({
        error: "Arquivo não é uma imagem válida ou formato não suportado",
        details: "Apenas JPEG, PNG e WEBP são permitidos",
      });
    }

    // 2) tamanho (também dá pra usar f.size, mas garantimos pelo buffer)
    if (buf.length > 5 * 1024 * 1024) {
      return res.status(400).json({
        error: "Arquivo muito grande",
        details: "Tamanho máximo permitido: 5MB",
      });
    }

    // 3) reforço por mime/extensão
    const allowedMimes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    const ext = path.extname(f.originalname || "").toLowerCase();
    const allowedExt = [".jpg", ".jpeg", ".png", ".webp"];

    if (!allowedMimes.includes(f.mimetype) || !allowedExt.includes(ext)) {
      return res.status(400).json({ error: "Formato não permitido" });
    }

    console.log(`✅ [FILE VALIDATION] Arquivo ${f.originalname || "(sem nome)"} validado com sucesso`);
    return next();
  } catch (err: any) {
    console.error("❌ [FILE VALIDATION] Erro:", err?.message || err);
    if (!res.headersSent) {
      return res.status(500).json({
        error: "Falha ao validar imagem",
        details: err?.message || String(err),
      });
    }
  }
}

// Configuração segura do multer com validação aprimorada
const secureUpload = multer({
  storage: storage_multer,
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB máximo para segurança
    files: 1, // Apenas um arquivo por vez
  },
  fileFilter: (req, file, cb) => {
    // Validação primária por MIME type
    const allowedMimes = ["image/jpeg", "image/jpg", "image/png", "image/webp"];
    if (!allowedMimes.includes(file.mimetype)) {
      return cb(
        new Error("Formato não permitido. Use apenas JPEG, PNG ou WEBP")
      );
    }

    // Validação de extensão de arquivo
    const allowedExtensions = [".jpg", ".jpeg", ".png", ".webp"];
    const fileExtension = path.extname(file.originalname).toLowerCase();
    if (!allowedExtensions.includes(fileExtension)) {
      return cb(new Error("Extensão de arquivo não permitida"));
    }

    cb(null, true);
  },
});

