// =============================================================================
// LEITURA DA PLANILHA FINANCEIRA - Metas 2025
// =============================================================================

interface MetasCategoria {
  categoria: string;
  grupo: "RECEITAS" | "DESPESAS";
  metas: {
    janeiro: number;
    fevereiro: number;
    marco: number;
    abril: number;
    maio: number;
    junho: number;
    julho: number;
    agosto: number;
    setembro: number;
    outubro: number;
    novembro: number;
    dezembro: number;
    total: number;
  };
}

interface MetasPlanilha {
  receitas: MetasCategoria[];
  despesas: MetasCategoria[];
  timestamp: string;
}

/**
 * Lê a planilha Excel e extrai as metas de RECEITAS e DESPESAS
 */
function lerMetasPlanilha(): MetasPlanilha {
  const planilhaPath =
    "attached_assets/PLANEJAMENTO FINANCEIRO 2025 COM FAVELA (1)_1759772504530.xlsx";

  console.log("📊 [PLANILHA] Lendo metas financeiras de:", planilhaPath);

  try {
    // Ler arquivo Excel
    const workbook = XLSX.readFile(planilhaPath);
    const sheet = workbook.Sheets["GERAL"];

    if (!sheet) {
      throw new Error("Aba GERAL não encontrada na planilha");
    }

    // Converter para array de arrays
    const data = XLSX.utils.sheet_to_json(sheet, {
      header: 1,
      defval: "",
    }) as any[][];

    const receitas: MetasCategoria[] = [];
    const despesas: MetasCategoria[] = [];

    let blocoAtual: "RECEITAS" | "DESPESAS" | null = null;

    // Processar cada linha
    for (let i = 0; i < data.length; i++) {
      const row = data[i];

      // Detectar início dos blocos
      if (row[1] === "RECEITAS") {
        blocoAtual = "RECEITAS";
        console.log(
          `✅ [PLANILHA] Bloco RECEITAS encontrado na linha ${i + 1}`
        );
        continue;
      }

      if (row[1] === "DESPESAS") {
        blocoAtual = "DESPESAS";
        console.log(
          `✅ [PLANILHA] Bloco DESPESAS encontrado na linha ${i + 1}`
        );
        continue;
      }

      // Pular linhas vazias ou sem categoria
      if (!blocoAtual || !row[1] || typeof row[1] !== "string") {
        continue;
      }

      // Pular linhas de totais ou subtotais (geralmente em maiúsculas)
      const categoria = row[1].trim();
      if (categoria === "" || categoria === blocoAtual) {
        continue;
      }

      // Extrair valores mensais (colunas 2-13 = Jan-Dez)
      const metas = {
        janeiro: parseFloat(row[2]) || 0,
        fevereiro: parseFloat(row[3]) || 0,
        marco: parseFloat(row[4]) || 0,
        abril: parseFloat(row[5]) || 0,
        maio: parseFloat(row[6]) || 0,
        junho: parseFloat(row[7]) || 0,
        julho: parseFloat(row[8]) || 0,
        agosto: parseFloat(row[9]) || 0,
        setembro: parseFloat(row[10]) || 0,
        outubro: parseFloat(row[11]) || 0,
        novembro: parseFloat(row[12]) || 0,
        dezembro: parseFloat(row[13]) || 0,
        total: parseFloat(row[14]) || 0,
      };

      // Adicionar ao array correspondente
      const metaCategoria: MetasCategoria = {
        categoria,
        grupo: blocoAtual,
        metas,
      };

      if (blocoAtual === "RECEITAS") {
        receitas.push(metaCategoria);
      } else {
        despesas.push(metaCategoria);
      }
    }

    console.log(
      `✅ [PLANILHA] Metas extraídas: ${receitas.length} categorias de RECEITAS, ${despesas.length} categorias de DESPESAS`
    );

    return {
      receitas,
      despesas,
      timestamp: new Date().toISOString(),
    };
  } catch (error) {
    console.error("❌ [PLANILHA] Erro ao ler planilha:", error);
    throw error;
  }
}

interface DadosDepartamento {
  departamento: string;
  contasReceber: number;
  contasPagar: number;
  saldo: number;
}

/**
 * Busca dados anuais do departamento do banco Digital Ocean (leitura direta, sem soma)
 * Os dados vêm da tabela conselho_dados_realizados_anual, que armazena os totais anuais diretamente
 */
async function obterDadosDepartamentoDoBanco(
  departamento: string,
  ano: number = 2025
): Promise<DadosDepartamento> {
  console.log(
    `📊 [DEPARTAMENTO DB ANUAL] Buscando dados anuais do banco para: ${departamento}, ano: ${ano}`
  );

  // Normalizar nome do departamento para busca
  const departamentoNormalizado = departamento.toUpperCase();

  // Buscar dados anuais diretos da nova tabela (não soma de meses!)
  const dadosAnuais = await db
    .select()
    .from(conselhoDadosRealizadosAnual)
    .where(
      and(
        eq(conselhoDadosRealizadosAnual.ano, ano),
        sql`UPPER(${conselhoDadosRealizadosAnual.departamento}) = ${departamentoNormalizado}`
      )
    );

  // Se encontrou dados, usar os valores diretos
  if (dadosAnuais.length > 0) {
    const dados = dadosAnuais[0];
    const contasReceber = parseFloat(dados.contasAReceber?.toString() || "0");
    const contasPagar = Math.abs(
      parseFloat(dados.contasAPagar?.toString() || "0")
    );
    const saldo = parseFloat(dados.saldo?.toString() || "0");

    console.log(
      `✅ [DEPARTAMENTO DB ANUAL] ${departamento}: Receber=R$ ${contasReceber.toFixed(
        2
      )}, Pagar=R$ ${contasPagar.toFixed(2)}, Saldo=R$ ${saldo.toFixed(2)}`
    );

    return {
      departamento,
      contasReceber,
      contasPagar,
      saldo,
    };
  }

  // Se não encontrou dados anuais, retornar zeros
  console.log(
    `⚠️ [DEPARTAMENTO DB ANUAL] Nenhum dado anual encontrado para: ${departamento}`
  );
  return {
    departamento,
    contasReceber: 0,
    contasPagar: 0,
    saldo: 0,
  };
}

/**
 * Fallback síncrono (mantido para compatibilidade)
 */
