  // Start OTP process - only for eligible users
  app.post("/api/auth/start-otp", async (req, res) => {
    try {
      const { phone } = req.body;

      if (!phone) {
        return res.status(400).json({ error: "Telefone é obrigatório" });
      }

      console.log(`📱 [START OTP] Initiating for phone: ${phone}`);

      try {
        // First check eligibility
        const normalizedPhone = normalizePhoneToE164(phone);
        const existingUser = await storage.getUserByTelefone(normalizedPhone);

        if (!existingUser) {
          console.log(
            `❌ [START OTP] User not eligible - payment required for: ${normalizedPhone}`
          );
          return res.status(402).json({
            error: "PAYMENT_REQUIRED",
            message:
              "Este número não está cadastrado. Complete o pagamento para se cadastrar.",
            eligible: false,
          });
        }

        console.log(
          `✅ [START OTP] User eligible: ${existingUser.nome} (${existingUser.id})`
        );

        // Special handling for test numbers
        const testNumbers = [
          "+5599999999999",
          "+5531999990001",
          "+5531999990002",
          "+5531999990003",
          "+5531998783003",
          "+5531987830003",
          "+5531999990004",
        ];

        if (testNumbers.some((testPhone) => normalizedPhone === testPhone)) {
          const codigo = "123456";
          verificationCodes.set(normalizedPhone, codigo);

          setTimeout(() => {
            verificationCodes.delete(normalizedPhone);
          }, 10 * 60 * 1000);

          return res.json({
            success: true,
            message: "Código de teste gerado",
            codigo: codigo, // Show code for test phones
          });
        }

        // Generate 6-digit verification code
        const codigo = Math.floor(100000 + Math.random() * 900000).toString();

        // Store verification code with multiple formats
        const storageKeys = [
          normalizedPhone,
          phone,
          normalizedPhone.replace("+", ""),
          phone.replace(/\D/g, ""),
        ];

        const uniqueKeys = [...new Set(storageKeys)];
        uniqueKeys.forEach((key) => {
          if (key && key.length > 0) {
            verificationCodes.set(key, codigo);
          }
        });

        setTimeout(() => {
          uniqueKeys.forEach((key) => {
            verificationCodes.delete(key);
          });
        }, 10 * 60 * 1000);

        try {
          // Send SMS via Twilio
          const client = getTwilioClient();
          await client.messages.create({
            body: `Seu código de acesso ao Clube do Grito é: ${codigo}`,
            from: process.env.TWILIO_PHONE_NUMBER || "+12345678901",
            to: normalizedPhone,
          });

          console.log(
            `✅ [START OTP] SMS sent to ${normalizedPhone} with code ${codigo}`
          );
          res.json({
            success: true,
            message: "Código enviado via SMS",
            phoneNormalized: normalizedPhone,
          });
        } catch (twilioError) {
          console.error("❌ [START OTP] Twilio error:", twilioError);
          // Still allow login with generated code for development
          res.json({
            success: true,
            message: "Código gerado (SMS indisponível)",
            codigo: codigo, // For development
            phoneNormalized: normalizedPhone,
          });
        }
      } catch (normalizationError: any) {
        console.error(
          `❌ [START OTP] Phone normalization error:`,
          normalizationError
        );
        return res.status(400).json({
          error: "Formato de telefone inválido",
          message:
            normalizationError.message || "Número de telefone deve ser válido",
        });
      }
    } catch (error: any) {
      console.error("❌ [START OTP] Error:", error);
      res.status(500).json({ error: "Erro ao enviar código OTP" });
    }
  });

  // Verify OTP and create session
  app.post("/api/auth/verify-otp", async (req, res) => {
    try {
      const { phone, code } = req.body;

      if (!phone || !code) {
        return res
          .status(400)
          .json({ error: "Telefone e código são obrigatórios" });
      }

      console.log(`🔍 [VERIFY OTP] Phone: ${phone}, Code: ${code}`);

      try {
        const normalizedPhone = normalizePhoneToE164(phone);

        // Search for verification code with multiple key formats
        const searchKeys = [
          normalizedPhone,
          phone,
          normalizedPhone.replace("+", ""),
          phone.replace(/\D/g, ""),
        ];

        let storedCode = "";
        let foundKey = "";

        for (const key of searchKeys) {
          const foundCode = verificationCodes.get(key);
          if (foundCode) {
            storedCode = foundCode;
            foundKey = key;
            break;
          }
        }

        if (!storedCode) {
          console.log(`❌ [VERIFY OTP] No code found for: ${phone}`);
          return res
            .status(400)
            .json({ error: "Código não encontrado ou expirado" });
        }

        if (storedCode !== code) {
          return res.status(400).json({ error: "Código inválido" });
        }

        // Remove verification code after successful verification
        searchKeys.forEach((key) => {
          verificationCodes.delete(key);
        });

        // Get user data
        const user = await storage.getUserByTelefone(normalizedPhone);

        if (!user) {
          console.log(
            `❌ [VERIFY OTP] User not found after verification: ${normalizedPhone}`
          );
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        console.log(
          `✅ [VERIFY OTP] Verification successful for user: ${user.nome} (${user.id})`
        );

        // Check donation status for existing donors
        let donationStatus = {
          isDonor: user.tipo === "doador",
          hasActiveSubscription: false,
          isExistingDonor: false,
        };

        if (user.tipo === "doador") {
          try {
            // VERIFICAÇÃO REAL NA STRIPE - Bloqueia login se não houver assinatura ativa
            console.log(
              `🔍 [VERIFY OTP] Verificando assinatura Stripe para doador: ${user.nome}`
            );

            // Buscar customerId do doador
            const [doadorInfo] = await db
              .select({
                id: doadores.id,
                stripeCustomerId: doadores.stripeCustomerId,
                status: doadores.status,
                ativo: doadores.ativo,
              })
              .from(doadores)
              .where(eq(doadores.userId, user.id))
              .limit(1);

            if (!doadorInfo) {
              console.log(
                `❌ [VERIFY OTP] Doador não encontrado na tabela doadores: ${user.id}`
              );
              return res.status(403).json({
                error: "SUBSCRIPTION_REQUIRED",
                message:
                  "Você precisa ter uma assinatura ativa para acessar. Faça uma doação para continuar.",
              });
            }

            // Se tem stripeCustomerId, verifica na Stripe
            if (doadorInfo.stripeCustomerId && stripe) {
              const subscriptions = await stripe.subscriptions.list({
                customer: doadorInfo.stripeCustomerId,
                status: "all",
                limit: 10,
              });

              const activeStatuses = ["active", "trialing"];
              const hasActiveStripeSubscription = subscriptions.data.some(
                (sub) => activeStatuses.includes(sub.status)
              );

              console.log(
                `🔍 [VERIFY OTP] Stripe subscriptions para ${user.nome}: ${subscriptions.data.length} total, ativas: ${hasActiveStripeSubscription}`
              );

              if (!hasActiveStripeSubscription) {
                console.log(
                  `⚠️ [VERIFY OTP] Assinatura inativa na Stripe, mas permitindo login para reativação: ${user.nome}`
                );
                donationStatus.hasActiveSubscription = false;
                donationStatus.needsReactivation = true;
              }

              donationStatus.hasActiveSubscription = true;
              donationStatus.isExistingDonor = true;
              console.log(
                `✅ [VERIFY OTP] Assinatura ativa confirmada na Stripe para: ${user.nome}`
              );
            } else {
              // Sem stripeCustomerId - verificar apenas banco local
              if (doadorInfo.status !== "paid" || !doadorInfo.ativo) {
                console.log(
                  `⚠️ [VERIFY OTP] Status local inativo, mas permitindo login para reativação: ${doadorInfo.status}, ativo: ${doadorInfo.ativo}`
                );
                donationStatus.hasActiveSubscription = false;
                donationStatus.needsReactivation = true;
              }
              donationStatus.hasActiveSubscription = true;
              donationStatus.isExistingDonor = true;
            }
          } catch (error) {
            console.error(
              "❌ [VERIFY OTP] Error checking Stripe subscription:",
              error
            );
            // Em caso de erro na verificação, bloqueia por segurança
            return res.status(403).json({
              error: "VERIFICATION_ERROR",
              message: "Erro ao verificar sua assinatura. Tente novamente.",
            });
          }
        }

        // Return user data with role and donation status
        res.json({
          success: true,
          user: {
            id: user.id,
            nome: user.nome,
            email: user.email || "",
            telefone: user.telefone,
            role: user.role || user.tipo || "user",
            conselhoStatus: user.conselhoStatus,
          },
          donationStatus,
        });
      } catch (normalizationError: any) {
        console.error(
          `❌ [VERIFY OTP] Phone normalization error:`,
          normalizationError
        );
        return res.status(400).json({
          error: "Formato de telefone inválido",
          message:
            normalizationError.message || "Número de telefone deve ser válido",
        });
      }
    } catch (error: any) {
      console.error("❌ [VERIFY OTP] Error:", error);
      res.status(500).json({ error: "Erro ao verificar código OTP" });
    }
  });

  // Function to normalize Brazilian phone number to international format
  function normalizePhoneNumber(phone: string): string {
    // Remove all non-digit characters
    const digits = phone.replace(/\D/g, "");

    // Handle different Brazilian phone formats
    if (digits.length === 11 && digits.startsWith("1")) {
      // Format: 11987654321 -> +5511987654321
      return `+55${digits}`;
    } else if (digits.length === 10) {
      // Format: 1187654321 -> +55111987654321 (add 9 for mobile)
      return `+55${digits.substring(0, 2)}9${digits.substring(2)}`;
    } else if (digits.length === 11) {
      // Format: 31987654321 -> +5531987654321
      return `+55${digits}`;
    }

    // Return original if format is unclear
    return phone;
  }

 // Send login code via SMS
app.post("/api/send-login-code", async (req, res) => {
  try {
    const { telefone } = req.body;

    console.log(
      `📱 SEND LOGIN CODE - Phone: ${telefone}, Time: ${new Date().toISOString()}`
    );

    if (!telefone) {
      return res.status(400).json({ error: "Telefone é obrigatório" });
    }

    // Handle original test phone number
    if (telefone === "+5599999999999" || telefone.includes("99999999999")) {
      const codigo = "123456";
      verificationCodes.set(telefone, codigo);

      setTimeout(() => {
        verificationCodes.delete(telefone);
      }, 10 * 60 * 1000);

      return res.json({
        success: true,
        message: "Código de teste gerado",
        codigo: codigo,
      });
    }

    // 🔒 SECURITY CHECK: verificar se telefone está cadastrado
    let existingUser: any = null;

    try {
      const phoneForDB = telefone.replace(/\D/g, "");

      console.log(
        `🔍 SECURITY CHECK - Verificando se telefone ${phoneForDB} está cadastrado...`
      );

      existingUser = await storage.getUserByTelefone(phoneForDB);

      if (!existingUser) {
        console.log(
          `❌ SECURITY BLOCK - Telefone ${phoneForDB} não está cadastrado no sistema`
        );
        return res.status(401).json({
          error: "Telefone não cadastrado no sistema",
          message:
            "Este número não está registrado. Para se cadastrar, acesse a página inicial.",
        });
      }

      console.log(
        `✅ SECURITY OK - Telefone cadastrado para usuário: ${existingUser.nome} (ID: ${existingUser.id})`
      );
    } catch (dbError) {
      console.error("Erro ao verificar telefone no banco:", dbError);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }

    // 🎯 INFLUENCIADOR: Não envia SMS, usa código do banco
    try {
      const phoneForInfluencer = telefone.replace(/\D/g, "");
      const phoneVariations = [
        phoneForInfluencer,
        phoneForInfluencer.startsWith("55")
          ? phoneForInfluencer
          : "55" + phoneForInfluencer,
        phoneForInfluencer.startsWith("55")
          ? phoneForInfluencer.substring(2)
          : phoneForInfluencer,
        "+" +
          (phoneForInfluencer.startsWith("55")
            ? phoneForInfluencer
            : "55" + phoneForInfluencer),
      ];

      const influencerCheck = await pool.query(
        `SELECT id, nome, influencer_code FROM users 
         WHERE influencer_code IS NOT NULL 
           AND influencer_code != ''
           AND (telefone = $1 OR telefone = $2 OR telefone = $3 OR telefone = $4)`,
        phoneVariations
      );

      if (influencerCheck.rows.length > 0) {
        const influencer = influencerCheck.rows[0];
        console.log(
          `🎯 [INFLUENCER] Detectado influenciador: ${influencer.nome} (ID: ${influencer.id})`
        );
        console.log(
          `🎯 [INFLUENCER] NÃO enviando SMS - código pré-definido será usado na verificação`
        );

        return res.json({
          success: true,
          message: "Digite seu código de acesso exclusivo",
          isInfluencer: true,
        });
      }
    } catch (influencerError) {
      console.log(
        "⚠️ [INFLUENCER] Erro ao verificar influenciador:",
        influencerError
      );
      // continua fluxo normal
    }

    // =====================================================
    // ✅ GATE: SEMPRE validar Stripe e NORMALIZAR banco
    // status no banco: paid | pending | canceled
    // =====================================================

    const userId = existingUser?.id;

    // 1) Puxa doadores (pega stripe ids)
    let doadorRow: any = null;
    try {
      const doadorQuery = await db
        .select({
          id: doadores.id,
          status: doadores.status,
          ativo: doadores.ativo,
          stripeCustomerId: doadores.stripeCustomerId,
          stripeSubscriptionId: doadores.stripeSubscriptionId,
          periodicidade: doadores.periodicidade,
          createdAt: doadores.createdAt,
          verificadoEm: doadores.verificadoEm,
        })
        .from(doadores)
        .where(eq(doadores.userId, userId))
        .orderBy(desc(doadores.createdAt))
        .limit(1);

      doadorRow = doadorQuery[0] || null;

      console.log("🔍 [LOGIN GATE] Banco (doadores) ->", {
        userId,
        found: !!doadorRow,
        status: doadorRow?.status,
        ativo: doadorRow?.ativo,
        stripeCustomerId: doadorRow?.stripeCustomerId,
        stripeSubscriptionId: doadorRow?.stripeSubscriptionId,
      });
    } catch (e: any) {
      console.log("⚠️ [LOGIN GATE] Falha ao checar doadores:", e.message);
      doadorRow = null;
    }

    const stripeCustomerId =
      doadorRow?.stripeCustomerId || existingUser?.stripeCustomerId || null;

    // Se não dá pra checar stripe, normaliza como canceled e bloqueia
    if (!stripeCustomerId || !stripe) {
      console.log(
        `⛔ [LOGIN GATE] Sem stripeCustomerId/Stripe (user ${userId}) -> bloqueando`
      );

      try {
        if (doadorRow?.id) {
          await db
            .update(doadores)
            .set({
              status: "canceled",
              ativo: false,
              verificadoEm: new Date(),
              updatedAt: new Date(),
              dataDesligamento: new Date(),
            } as any)
            .where(eq(doadores.id, doadorRow.id));
        } else {
          await db.insert(doadores).values({
            userId,
            plano: existingUser?.plano || "eco",
            valor: "0",
            stripeCustomerId: null,
            stripeSubscriptionId: null,
            status: "canceled",
            ativo: false,
            createdAt: new Date(),
            updatedAt: new Date(),
            verificadoEm: new Date(),
            dataDesligamento: new Date(),
          } as any);
        }
      } catch (e: any) {
        console.log("⚠️ [LOGIN GATE] Falha ao normalizar doadores:", e.message);
      }

      return res.status(402).json({
        success: false,
        error: "ASSINATURA_INEXISTENTE",
        reason: "SUBSCRIPTION_NOT_FOUND",
        message: "Não encontramos uma assinatura ativa para este número.",
      });
    }

    // 2) Stripe: buscar subs e decidir status
    let stripeDecision: {
      canLogin: boolean;
      dbStatus: "paid" | "pending" | "canceled";
      dbAtivo: boolean;
      reason: string;
      message: string;
      stripeSubId: string | null;
      stripeSubStatus: string | null;
      shouldSetDesligamento: boolean;
    } = {
      canLogin: false,
      dbStatus: "canceled",
      dbAtivo: false,
      reason: "SUBSCRIPTION_NOT_FOUND",
      message: "Não encontramos uma assinatura ativa para este número.",
      stripeSubId: null,
      stripeSubStatus: null,
      shouldSetDesligamento: true,
    };

    try {
      console.log(`🔍 [LOGIN GATE] Stripe check: customer=${stripeCustomerId}`);

      const subs = await stripe.subscriptions.list({
        customer: stripeCustomerId,
        status: "all",
        limit: 20,
      });

      // libera se active/trialing
      const activeSub = subs.data.find((s: any) =>
        ["active", "trialing"].includes(s.status)
      );

      if (activeSub) {
        stripeDecision = {
          canLogin: true,
          dbStatus: "paid",
          dbAtivo: true,
          reason: "SUBSCRIPTION_OK",
          message: "Assinatura ativa.",
          stripeSubId: activeSub.id,
          stripeSubStatus: activeSub.status,
          shouldSetDesligamento: false,
        };
      } else {
        // se existe alguma sub mas não ativa
        const anySub = subs.data[0] || null;

        if (!anySub) {
          stripeDecision = {
            canLogin: false,
            dbStatus: "canceled",
            dbAtivo: false,
            reason: "SUBSCRIPTION_NOT_FOUND",
            message: "Não encontramos uma assinatura para este número.",
            stripeSubId: null,
            stripeSubStatus: null,
            shouldSetDesligamento: true,
          };
        } else if (anySub.status === "paused") {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PAUSED",
            message: "Sua assinatura está pausada. Reative para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        } else if (
          ["past_due", "incomplete", "incomplete_expired", "unpaid"].includes(
            anySub.status
          )
        ) {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PENDING",
            message: "Sua assinatura está pendente. Regularize para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        } else if (anySub.status === "canceled") {
          stripeDecision = {
            canLogin: false,
            dbStatus: "canceled",
            dbAtivo: false,
            reason: "SUBSCRIPTION_CANCELED",
            message: "Sua assinatura foi cancelada. Reative para continuar.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: true,
          };
        } else {
          stripeDecision = {
            canLogin: false,
            dbStatus: "pending",
            dbAtivo: false,
            reason: "SUBSCRIPTION_PENDING",
            message: "Sua assinatura não está ativa no momento.",
            stripeSubId: anySub.id,
            stripeSubStatus: anySub.status,
            shouldSetDesligamento: false,
          };
        }
      }
    } catch (stripeErr: any) {
      console.log("⚠️ [LOGIN GATE] Stripe erro:", stripeErr.message);
      return res.status(503).json({
        success: false,
        error: "STRIPE_INDISPONIVEL",
        reason: "STRIPE_ERROR",
        message: "Erro ao validar assinatura. Tente novamente em instantes.",
      });
    }

    // 3) Normaliza banco SEMPRE com base na Stripe
    try {
      const baseUpdate: any = {
        stripeCustomerId: stripeCustomerId,
        stripeSubscriptionId: stripeDecision.stripeSubId,
        status: stripeDecision.dbStatus, // paid | pending | canceled
        ativo: stripeDecision.dbAtivo,
        verificadoEm: new Date(),
        updatedAt: new Date(),
      };

      if (stripeDecision.shouldSetDesligamento) {
        baseUpdate.dataDesligamento = new Date();
      } else {
        baseUpdate.dataDesligamento = null;
      }

      if (doadorRow?.id) {
        await db
          .update(doadores)
          .set(baseUpdate)
          .where(eq(doadores.id, doadorRow.id));
      } else {
        await db.insert(doadores).values({
          userId,
          plano: existingUser?.plano || "eco",
          valor: "0",
          stripeCustomerId: stripeCustomerId,
          stripeSubscriptionId: stripeDecision.stripeSubId,
          status: stripeDecision.dbStatus,
          ativo: stripeDecision.dbAtivo,
          createdAt: new Date(),
          updatedAt: new Date(),
          verificadoEm: new Date(),
          dataDesligamento: stripeDecision.shouldSetDesligamento
            ? new Date()
            : null,
        } as any);
      }

      await db
        .update(users)
        .set({
          stripeCustomerId: stripeCustomerId,
          stripeSubscriptionId: stripeDecision.stripeSubId,
          subscriptionStatus: stripeDecision.stripeSubStatus,
          ativo: stripeDecision.dbAtivo,
        } as any)
        .where(eq(users.id, userId));

      console.log("✅ [LOGIN GATE] Banco normalizado via Stripe:", {
        userId,
        dbStatus: stripeDecision.dbStatus,
        dbAtivo: stripeDecision.dbAtivo,
        stripeSubId: stripeDecision.stripeSubId,
        stripeSubStatus: stripeDecision.stripeSubStatus,
      });
    } catch (e: any) {
      console.log("⚠️ [LOGIN GATE] Falha ao atualizar banco:", e.message);
      // opcional: se quiser bloquear quando falhar update, aqui seria o lugar
    }

    // 4) Decide login
    if (!stripeDecision.canLogin) {
      return res.status(402).json({
        success: false,
        error:
          stripeDecision.dbStatus === "pending"
            ? "ASSINATURA_PENDENTE"
            : "ASSINATURA_INATIVA",
        reason: stripeDecision.reason,
        message: stripeDecision.message,
      });
    }

    // =====================================================
    // ✅ Só aqui gera e envia o código (assinatura OK)
    // =====================================================

    const codigo = Math.floor(100000 + Math.random() * 900000).toString();

    const phoneDigitsOnly = telefone.replace(/\D/g, "");
    const phoneWith55 = phoneDigitsOnly.startsWith("55")
      ? phoneDigitsOnly
      : "55" + phoneDigitsOnly;
    const phoneWithout55 = phoneDigitsOnly.startsWith("55")
      ? phoneDigitsOnly.substring(2)
      : phoneDigitsOnly;

    const allFormats = [
      telefone,
      phoneDigitsOnly,
      phoneWith55,
      phoneWithout55,
      "+" + phoneWith55,
      "+" + phoneDigitsOnly,
    ];

    allFormats.forEach((format) => {
      verificationCodes.set(format, codigo);
    });

    setTimeout(() => {
      allFormats.forEach((format) => {
        verificationCodes.delete(format);
      });
    }, 10 * 60 * 1000);

    try {
      let normalizedPhone = telefone.replace(/\D/g, "");
      if (!normalizedPhone.startsWith("55")) normalizedPhone = "55" + normalizedPhone;
      const twilioPhone = "+" + normalizedPhone;

      console.log(`📱 LOGIN SMS - Original: ${telefone}, Normalized: ${twilioPhone}`);
      console.log(`🔑 CÓDIGO GERADO: ${codigo}`);

      const client = getTwilioClient();
      await client.messages.create({
        body: `Seu código de acesso ao Clube do Grito é: ${codigo}`,
        from: process.env.TWILIO_PHONE_NUMBER || "+12345678901",
        to: twilioPhone,
      });

      console.log(`✅ LOGIN SMS SENT to ${twilioPhone} with code ${codigo}`);
      return res.json({ success: true, message: "Código enviado via SMS" });
    } catch (twilioError) {
      console.error("Twilio error:", twilioError);
      return res.json({
        success: true,
        message: "Código gerado (SMS indisponível)",
        codigo: codigo,
      });
    }
  } catch (error: any) {
    console.error("Error sending login code:", error);
    return res.status(500).json({ error: "Erro ao enviar código" });
  }
});

    // Verify login code (regular users - restored to original)
  // ✅ ROTA COMPLETA (corrigida) — /api/verify-login-code
  app.post("/api/verify-login-code", async (req, res) => {
  try {
    const { telefone, codigo } = req.body;

    console.log(
      `🔍 VERIFY LOGIN CODE - Phone: ${telefone}, Code: ${codigo}, Time: ${new Date().toISOString()}`
    );

    if (!telefone || !codigo) {
      console.log(`❌ MISSING DATA - Phone: ${telefone}, Code: ${codigo}`);
      return res.status(400).json({ error: "Telefone e código são obrigatórios" });
    }

    // =====================================================
    // CÓDIGO DE VERIFICAÇÃO (normal + influencer)
    // =====================================================
    const normalizedForCheck = telefone.replace(/\D/g, "").replace(/^55/, "");
    const possibleKeys = [
      telefone,
      normalizedForCheck,
      `+55${normalizedForCheck}`,
      `+5531${normalizedForCheck.substring(2)}`,
    ];

    let storedCode: string | null = null;
    let matchedKey: string | null = null;

    for (const key of possibleKeys) {
      storedCode = verificationCodes.get(key);
      if (storedCode) {
        matchedKey = key;
        break;
      }
    }

    // 🎯 INFLUENCER: Se não tem código armazenado, verificar no banco
    let isInfluencer = false;
    if (!storedCode) {
      try {
        const phoneForInfluencer = telefone.replace(/\D/g, "");
        const phoneWithoutCountry = phoneForInfluencer.replace(/^55/, "");
        const phoneWith55 = "55" + phoneWithoutCountry;

        console.log("🎯 [INFLUENCER VERIFY] Verificando se código é de influencer no banco");

        const influencerResult = await pool.query(
          `SELECT id, nome, telefone, influencer_code 
           FROM users 
           WHERE influencer_code = $1 
             AND (
               regexp_replace(telefone, '[^0-9]', '', 'g') = $2
               OR regexp_replace(telefone, '[^0-9]', '', 'g') = $3
               OR regexp_replace(telefone, '[^0-9]', '', 'g') = $4
             )`,
          [codigo, phoneForInfluencer, phoneWith55, phoneWithoutCountry]
        );

        if (influencerResult.rows && influencerResult.rows.length > 0) {
          const influencer = influencerResult.rows[0] as any;
          console.log("🎯 [INFLUENCER] ✅ Código válido para:", influencer.nome, "- ID:", influencer.id);
          isInfluencer = true;
          storedCode = codigo;
        } else {
          console.log("🎯 [INFLUENCER] Código não corresponde a nenhum influencer");
          return res.status(400).json({
            error: "Código de verificação não encontrado ou expirado",
          });
        }
      } catch (influencerError) {
        console.log("⚠️ [INFLUENCER] Erro ao verificar influencer:", influencerError);
        return res.status(400).json({
          error: "Código de verificação não encontrado ou expirado",
        });
      }
    }

    if (!isInfluencer && storedCode !== codigo) {
      return res.status(400).json({ error: "Código de verificação inválido" });
    }

    // Remove código após sucesso
    verificationCodes.delete(telefone);
    if (matchedKey) verificationCodes.delete(matchedKey);
    for (const key of possibleKeys) verificationCodes.delete(key);

    // =====================================================
    // DEFINIR PAPEL / ROLE
    // =====================================================
    let papel = "user";
    let needsCouncilApproval = false;
    let professorTipo: string | null = null;

    let user = await storage.getUserByTelefone(telefone);

    if (!user) {
      user = await storage.createUser({
        cpf: `TEMP${telefone.slice(-8)}`,
        nome: "Usuário",
        sobrenome: "",
        telefone,
        email: "",
        plano: "eco",
      });
    }

    if (user.role === "leo") {
      papel = "leo";
      needsCouncilApproval = false;
      console.log(`✅ LEO MARTINS LOGIN - User ID: ${user.id}, Role: leo`);
    } else if (user.role && user.role !== "user") {
      papel = user.role;
      needsCouncilApproval = false;
      console.log(`✅ USER ROLE FROM DB - Phone: ${telefone}, Role: ${user.role}`);
    }

    if (papel === "user") {
      if (telefone === "+5531999999999" || telefone === "31999999999") {
        papel = "admin";
      } else if (telefone === "+5531888888888" || telefone === "31888888888") {
        papel = "conselho";
      } else {
        const userType = user.tipo || "user";
        console.log(`👤 USER TYPE CHECK - Phone: ${telefone}, Type: ${userType}`);

        if (userType === "doador") {
          papel = "doador";
          needsCouncilApproval = false;
          console.log(`✅ DOADOR LOGIN - No approval needed`);
        } else {
          const conselhoStatus = user.conselhoStatus;

          if (conselhoStatus === "aprovado") {
            papel = "conselho";
            needsCouncilApproval = false;
          } else if (conselhoStatus === "pendente") {
            needsCouncilApproval = true;
          } else if (conselhoStatus === "recusado") {
            needsCouncilApproval = true;
          } else {
            needsCouncilApproval = false;
          }
        }
      }
    }

    // ✅ Se chegou aqui, passou pelo gate do /send-login-code (assinatura OK)
    return res.json({
      success: true,
      user: {
        id: user.id,
        nome: user.nome || "Usuário",
        email: user.email,
        telefone: user.telefone,
        papel,
        professorTipo,
      },
      conselhoStatus: user.conselhoStatus || null,
      needsCouncilApproval,
      hasActiveSubscription: true,
    });
  } catch (error: any) {
    console.error("Error verifying login code:", error);
    return res.status(500).json({ error: "Erro ao verificar código" });
  }
});

  // 🎯 FUNÇÃO HELPER: Verifica e completa missão de referral automaticamente
  async function checkAndCompleteMissaoReferral(
    userId: number,
    missaoId: number
  ) {
    try {
      console.log(
        `🔍 [REFERRAL AUTO] Verificando se missão ${missaoId} deve ser completada para usuário ${userId}`
      );

      // 1. Verificar se a missão já foi concluída (evitar duplicação)
      const missaoJaConcluida = await db
        .select()
        .from(missoesConcluidas)
        .where(
          and(
            eq(missoesConcluidas.userId, userId),
            eq(missoesConcluidas.missaoId, missaoId)
          )
        )
        .limit(1);

      if (missaoJaConcluida[0]) {
        console.log(
          `⚠️ [REFERRAL AUTO] Missão ${missaoId} já foi concluída pelo usuário ${userId}. Pulando.`
        );
        return;
      }

      // 2. Buscar dados da missão
      const missao = await db
        .select()
        .from(missoesSemanais)
        .where(eq(missoesSemanais.id, missaoId))
        .limit(1);

      if (!missao[0]) {
        console.error(`❌ [REFERRAL AUTO] Missão ${missaoId} não encontrada`);
        return;
      }

      // 3. Contar referrals completos para esta missão
      const referralsCompletos = await db
        .select()
        .from(referrals)
        .where(
          and(
            eq(referrals.referrerUserId, userId),
            eq(referrals.missaoId, missaoId),
            eq(referrals.status, "completo")
          )
        );

      const quantidadeNecessaria = missao[0].quantidadeAmigos || 1;
      const cadastrosCompletos = referralsCompletos.length;

      console.log(
        `📊 [REFERRAL AUTO] Usuário ${userId}, Missão ${missaoId}: ${cadastrosCompletos}/${quantidadeNecessaria} referrals completos`
      );

      // 4. Verificar se atingiu o threshold
      if (cadastrosCompletos >= quantidadeNecessaria) {
        console.log(
          `🎯 [REFERRAL AUTO] Threshold atingido! Completando missão ${missaoId} para usuário ${userId}`
        );

        // 5. Dar gritos pela missão completa
        const { addGritos } = await import("./gritosSystem");
        await addGritos(
          userId,
          missao[0].recompensaGritos || 200,
          `Missão de referral completada: "${missao[0].titulo}" - ${cadastrosCompletos} amigos convidados com sucesso`
        );

        // 6. Marcar missão como concluída
        await db
          .insert(missoesConcluidas)
          .values({
            userId: userId,
            missaoId: missaoId,
            gritosRecebidos: missao[0].recompensaGritos || 200,
            fotoComprovante: null, // Referrals não precisam de foto
            evidenciaTexto: `Referral automático: ${cadastrosCompletos} cadastros completados`,
            evidenceType: "link" as any, // Marcar como tipo link
          })
          .onConflictDoNothing();

        console.log(
          `✅ [REFERRAL AUTO] Missão ${missaoId} completada automaticamente para usuário ${userId}! ${
            missao[0].recompensaGritos || 200
          } gritos adicionados.`
        );
      } else {
        console.log(
          `⏳ [REFERRAL AUTO] Missão ${missaoId} ainda não completada. Progresso: ${cadastrosCompletos}/${quantidadeNecessaria}`
        );
      }
    } catch (error) {
      console.error(
        `❌ [REFERRAL AUTO] Erro ao verificar completude da missão ${missaoId} para usuário ${userId}:`,
        error
      );
    }
  }

  // 🎯 FUNÇÃO HELPER: Verifica e completa missões de check-in automaticamente
  async function checkAndCompleteCheckinMissions(
    userId: number,
    diasConsecutivos: number
  ) {
    try {
      console.log(
        `🔍 [CHECKIN AUTO] Verificando missões de check-in para usuário ${userId} com ${diasConsecutivos} dias consecutivos`
      );

      // 1. Buscar missões de check-in ativas (checkin_semanal, checkin_diario)
      const missoesCheckin = await db
        .select()
        .from(missoesSemanais)
        .where(
          and(
            eq(missoesSemanais.ativo, true),
            sql`${missoesSemanais.tipoMissao} IN ('checkin_semanal', 'checkin_diario', 'check_in_consecutivo')`
          )
        );

      if (missoesCheckin.length === 0) {
        console.log(
          `⚠️ [CHECKIN AUTO] Nenhuma missão de check-in ativa encontrada`
        );
        return;
      }

      for (const missao of missoesCheckin) {
        // 2. Verificar se a missão já foi concluída
        const missaoJaConcluida = await db
          .select()
          .from(missoesConcluidas)
          .where(
            and(
              eq(missoesConcluidas.userId, userId),
              eq(missoesConcluidas.missaoId, missao.id)
            )
          )
          .limit(1);

        if (missaoJaConcluida[0]) {
          console.log(
            `⚠️ [CHECKIN AUTO] Missão ${missao.id} já foi concluída pelo usuário ${userId}. Pulando.`
          );
          continue;
        }

        // 3. Verificar se atingiu a quantidade de dias necessários
        const diasNecessarios = missao.diasNecessarios || missao.quantidadeAmigos || 3; // Padrão: 3 dias consecutivos
        
        console.log(`📊 [CHECKIN AUTO] Usuário ${userId}, Missão ${missao.id} "${missao.titulo}": ${diasConsecutivos}/${diasNecessarios} dias consecutivos`);

        if (diasConsecutivos >= diasNecessarios) {
          console.log(
            `🎯 [CHECKIN AUTO] Threshold atingido! Completando missão ${missao.id} para usuário ${userId}`
          );

          // 4. Dar gritos pela missão completa
          const { addGritos } = await import("./gritosSystem");
          await addGritos(
            userId,
            missao.recompensaGritos || 150,
            `Missão de check-in completada: "${missao.titulo}" - ${diasConsecutivos} dias consecutivos`
          );

          // 5. Marcar missão como concluída
          await db
            .insert(missoesConcluidas)
            .values({
              userId: userId,
              missaoId: missao.id,
              gritosRecebidos: missao.recompensaGritos || 150,
              fotoComprovante: null,
              evidenciaTexto: `Check-in automático: ${diasConsecutivos} dias consecutivos`,
              evidenceType: "automatico" as any,
            })
            .onConflictDoNothing();

          console.log(
            `✅ [CHECKIN AUTO] Missão ${
              missao.id
            } completada automaticamente para usuário ${userId}! ${
              missao.recompensaGritos || 150
            } gritos adicionados.`
          );
        } else {
          console.log(
            `⏳ [CHECKIN AUTO] Missão ${missao.id} ainda não completada. Progresso: ${diasConsecutivos}/${diasNecessarios}`
          );
        }
      }
    } catch (error) {
      console.error(
        `❌ [CHECKIN AUTO] Erro ao verificar missões de check-in para usuário ${userId}:`,
        error
      );
    }
  }

  // Verify SMS code (existing registration flow)
  app.post("/api/verify", async (req, res) => {
    try {
      const { telefone, codigo } = verificationSchema.parse(req.body);

      const user = await storage.getUserByTelefone(telefone);
      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Check stored verification code
      const storedCode = verificationCodes.get(telefone);

      if (!storedCode) {
        return res
          .status(400)
          .json({ error: "Código de verificação não encontrado ou expirado" });
      }

      if (storedCode !== codigo) {
        return res
          .status(400)
          .json({ error: "Código de verificação inválido" });
      }

      // Update user verification status
      const updatedUser = await storage.updateUserVerification(user.id, true);

      // 🔍 VERIFICAR STATUS DE DOAÇÃO: Para redirecionamento correto
      let donationStatus = null;
      try {
        const doadorRecord = await db
          .select({
            id: doadores.id,
            status: doadores.status,
            plano: doadores.plano,
            stripeSubscriptionId: doadores.stripeSubscriptionId,
          })
          .from(doadores)
          .where(eq(doadores.userId, updatedUser.id))
          .limit(1);

        if (doadorRecord.length > 0) {
          const doacao = doadorRecord[0];
          donationStatus = {
            isExistingDonor: true,
            status: doacao.status, // 'paid', 'pending', 'cancelled', etc.
            plan: doacao.plano,
            hasActiveSubscription:
              doacao.status === "paid" && doacao.stripeSubscriptionId,
          };
          console.log(
            `✅ [VERIFY] Doador existente encontrado: ${updatedUser.nome}, status: ${doacao.status}`
          );
        } else {
          donationStatus = {
            isExistingDonor: false,
            status: null,
            plan: null,
            hasActiveSubscription: false,
          };
          console.log(`🔍 [VERIFY] Usuário não é doador: ${updatedUser.nome}`);
        }
      } catch (error) {
        console.error("Erro ao verificar status de doação:", error);
        donationStatus = {
          isExistingDonor: false,
          status: null,
          plan: null,
          hasActiveSubscription: false,
        };
      }

      // 🎯 PROCESSAR REFERRAL: Completar o referral se existir
      const referralKey = `referral_${telefone}`;
      const referralDataStr = verificationCodes.get(referralKey);

      if (referralDataStr) {
        try {
          const referralInfo = JSON.parse(referralDataStr);

          // Atualizar referral com o novo usuário e marcar como completo
          await db
            .update(referrals)
            .set({
              referredUserId: updatedUser.id,
              status: "completo",
              completadoEm: new Date(),
            })
            .where(eq(referrals.id, referralInfo.referralId));

          // 🎯 NOVO: Verificar se a missão deve ser completada automaticamente
          await checkAndCompleteMissaoReferral(
            referralInfo.referrerUserId,
            referralInfo.missaoId
          );

          console.log(
            `✅ [REFERRAL] Completado! Usuário ${updatedUser.id} (${updatedUser.nome}) indicado por usuário ${referralInfo.referrerUserId}. ${referralInfo.gritosRecompensa} gritos adicionados.`
          );

          // Remover dados do referral
          verificationCodes.delete(referralKey);
        } catch (error) {
          console.error("Erro ao processar referral:", error);
        }
      }

      // Remove verification code after successful verification
      verificationCodes.delete(telefone);

      res.json({
        success: true,
        user: {
          id: updatedUser.id,
          nome: updatedUser.nome,
          plano: updatedUser.plano,
          role: updatedUser.role, // ✅ RETORNAR ROLE REAL DO BANCO
          conselhoStatus: updatedUser.conselhoStatus, // ✅ RETORNAR STATUS DE CONSELHO
          donationStatus, // ✅ RETORNAR STATUS DE DOAÇÃO PARA REDIRECIONAMENTO CORRETO
        },
      });
    } catch (error: any) {
      console.error("Error verifying code:", error);
      if (error instanceof z.ZodError) {
        return res
          .status(400)
          .json({ error: "Dados inválidos", details: error.errors });
      }
      res.status(500).json({ error: "Erro ao verificar código" });
    }
  });

  // Send SMS code for donation flow
  app.post("/api/auth/send-sms", async (req, res) => {
    try {
      const { phone } = req.body;

      const e164 = toE164BR(phone);
      if (!e164) {
        return res.status(400).json({ error: "Número de telefone inválido" });
      }

      // ✅ Permitir envio de SMS mesmo se usuário já existir (para verificação de identidade no fluxo de doação)

      // Twilio sempre com E.164
      const twilioPhone = e164;

      // gera código etc...
      const codigo = Math.floor(100000 + Math.random() * 900000).toString();

      let client;
      try {
        client = getTwilioClient();
      } catch (e: any) {
        console.error("[SMS] Erro na configuração do Twilio", e.message);
        return res.status(503).json({
          error: "SMS Indisponivel no momento, tente novamente mais tarde",
        });
      }

      try {
        await client.messages.create({
          body: `Seu código de verificação do Clube do Grito é: ${codigo}`,
          from: process.env.TWILIO_PHONE_NUMBER!,
          to: twilioPhone,
        });
      } catch (e: any) {
        console.error("[SMS] Falha no envio de SMS", e?.code, e?.message);
        return res.status(502).json({ error: "Falha ao enviar SMS" });
      }

      console.log(`✅ SMS SENT to ${twilioPhone} with code ${codigo}`);
      res.json({ success: true, message: "Código enviado via SMS" });

      // Armazena o código em várias chaves (ok manter sua estratégia)
      const storageKeys = [
        twilioPhone, // +5511...
        twilioPhone.replace("+", ""), // 5511...
        (phone || "").replace(/\D/g, ""), // 5511... ou 11...
      ];
      const uniqueKeys = [...new Set(storageKeys.filter(Boolean))];
      uniqueKeys.forEach((k) => verificationCodes.set(k, codigo));
      setTimeout(
        () => uniqueKeys.forEach((k) => verificationCodes.delete(k)),
        15 * 60 * 1000
      );
    } catch (error) {
      console.error("Error sending SMS code:", error);
      res.status(500).json({ error: "Erro ao enviar código SMS" });
    }
  });

  // Login direto por e-mail para conselheiros e patrocinadores
  app.post("/api/auth/login-email", async (req, res) => {
    try {
      const { email } = req.body;

      if (!email || !email.trim()) {
        return res.status(400).json({ error: "E-mail é obrigatório" });
      }

      const cleanEmail = email.trim().toLowerCase();
      console.log(`📧 [EMAIL LOGIN] Tentativa de login: ${cleanEmail}`);

      // 🔐 Verificar se é conselheiro autorizado (busca no banco de dados)
      const [conselheiroDb] = await db
        .select()
        .from(conselheiros)
        .where(
          and(eq(conselheiros.email, cleanEmail), eq(conselheiros.ativo, true))
        );
      const isConselho = !!conselheiroDb;

      // Se não é conselheiro, verificar se é patrocinador existente
      let isPatrocinador = false;
      let user = null;

      if (!isConselho) {
        console.log(
          `🔍 [EMAIL LOGIN] Não é conselheiro, verificando se é patrocinador: ${cleanEmail}`
        );
        user = await storage.getUserByEmail(cleanEmail);

        if (user) {
          console.log(
            `👤 [EMAIL LOGIN] Usuário encontrado - ID: ${user.id}, Nome: ${user.nome}, Role: ${user.role}`
          );

          if (user.role === "patrocinador") {
            isPatrocinador = true;
            console.log(
              `✅ [EMAIL LOGIN] E-mail de patrocinador confirmado: ${cleanEmail}`
            );
          } else {
            console.log(
              `📋 [EMAIL LOGIN] Usuário não é patrocinador nem conselheiro. Verificando solicitação: ${cleanEmail}`
            );
            const [existente] = await db.select().from(conselheiros).where(eq(conselheiros.email, cleanEmail));
            if (existente && existente.tipo === "recusado") {
              return res.status(403).json({
                rejected: true,
                error: "Seu acesso ao Conselho foi negado pelo administrador.",
              });
            }
            if (!existente) {
              await db.insert(conselheiros).values({
                email: cleanEmail,
                nome: user.nome || cleanEmail,
                tipo: "conselho",
                ativo: false,
              });
            }
            return res.status(202).json({
              pendingApproval: true,
              message: "Sua solicitação de acesso ao Conselho foi enviada. Aguarde aprovação do administrador.",
            });
          }
        } else {
          console.log(
            `📋 [EMAIL LOGIN] E-mail não encontrado no sistema. Verificando solicitação: ${cleanEmail}`
          );
          const [existente] = await db.select().from(conselheiros).where(eq(conselheiros.email, cleanEmail));
          if (existente && existente.tipo === "recusado") {
            return res.status(403).json({
              rejected: true,
              error: "Seu acesso ao Conselho foi negado pelo administrador.",
            });
          }
          if (!existente) {
            await db.insert(conselheiros).values({
              email: cleanEmail,
              nome: cleanEmail,
              tipo: "conselho",
              ativo: false,
            });
          }
          return res.status(202).json({
            pendingApproval: true,
            message: "Sua solicitação de acesso ao Conselho foi enviada. Aguarde aprovação do administrador.",
          });
        }
      } else {
        console.log(
          `✅ [EMAIL LOGIN] E-mail de conselheiro confirmado: ${cleanEmail}`
        );
      }

      // Buscar ou criar usuário para conselheiros
      if (isConselho) {
        if (!user) {
          user = await storage.getUserByEmail(cleanEmail);
        }

        if (!user) {
          // Criar usuário conselheiro automaticamente
          console.log(
            `👤 [EMAIL LOGIN] Criando novo usuário conselheiro: ${cleanEmail}`
          );

          user = await storage.createUser({
            cpf: "00000000000",
            nome: "Membro do Conselho",
            telefone: "+5500000000000",
            email: cleanEmail,
            role: "conselho",
            verificado: true,
            conselhoStatus: "aprovado",
          });
        } else if (user.role !== "conselho") {
          // Atualizar usuário existente para ter acesso ao conselho
          console.log(
            `🔄 [EMAIL LOGIN] Atualizando role para conselho: ${cleanEmail}`
          );

          user = await storage.updateUser(user.id, {
            role: "conselho",
            verificado: true,
            conselhoStatus: "aprovado",
          });
        }
      }

      const finalRole = isPatrocinador ? "patrocinador" : "conselho";
      console.log(
        `✅ [EMAIL LOGIN] Login bem-sucedido para ${finalRole}: ${user!.id} - ${
          user!.nome
        }`
      );

      // Retornar dados do usuário para login
      res.json({
        success: true,
        user: {
          id: user!.id,
          nome: user!.nome,
          email: user!.email,
          telefone: user!.telefone,
          papel: finalRole,
          verificado: true,
          conselhoStatus: isConselho ? "aprovado" : undefined,
        },
      });
    } catch (error: any) {
      console.error("❌ [EMAIL LOGIN] Erro:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Verify SMS code for donation flow
  app.post("/api/auth/verify-sms", async (req, res) => {
    try {
      // Aceita tanto phone/code quanto telefone/codigo
      const { phone, telefone, code, codigo } = req.body;

      const finalPhone = phone || telefone;
      const finalCode = code || codigo;

      if (!finalPhone || !finalCode) {
        return res
          .status(400)
          .json({ error: "Telefone e código são obrigatórios" });
      }

      // Padronizar telefone para formato +55...
      let normalizedPhone = finalPhone.replace(/\D/g, "");
      if (!normalizedPhone.startsWith("55")) {
        normalizedPhone = "55" + normalizedPhone;
      }
      const phoneKey = "+" + normalizedPhone;

      console.log(
        `🔍 DONATION FLOW VERIFY - Phone: ${finalPhone}, Normalized: ${phoneKey}, Code: ${finalCode}`
      );

      // Buscar código armazenado
      const storedCode = verificationCodes.get(phoneKey);

      if (!storedCode) {
        console.log(`❌ NO CODE FOUND for key: ${phoneKey}`);
        return res
          .status(400)
          .json({ error: "Código de verificação não encontrado ou expirado" });
      }

      if (storedCode !== finalCode) {
        return res
          .status(400)
          .json({ error: "Código de verificação inválido" });
      }

      // Apagar o código usado para evitar reuso
      verificationCodes.delete(phoneKey);

      console.log(`✅ SMS VERIFICATION SUCCESS for ${phoneKey}`);

      res.json({ success: true, message: "Código verificado com sucesso" });
    } catch (error: any) {
      console.error("❌ Error verifying SMS code:", error);
      res.status(500).json({ error: "Erro ao verificar código SMS" });
    }
  });

