  app.get("/api/conselho/dados-realizados", async (req, res) => {
    try {
      const { ano, mes, departamento } = req.query;

      console.log(
        `📊 [CONSELHO REALIZADOS] Buscando dados - Ano: ${
          ano || "todos"
        }, Mês: ${mes || "todos"}, Departamento: ${departamento || "todos"}`
      );

      // Construir query com filtros opcionais
      let query = db.select().from(conselhoDadosRealizados);

      const conditions: any[] = [];
      if (ano)
        conditions.push(
          eq(conselhoDadosRealizados.ano, parseInt(ano as string))
        );
      if (mes)
        conditions.push(
          eq(conselhoDadosRealizados.mes, parseInt(mes as string))
        );
      if (departamento && departamento !== "TODOS") {
        conditions.push(
          eq(conselhoDadosRealizados.departamento, departamento as string)
        );
      }

      if (conditions.length > 0) {
        query = query.where(and(...conditions)) as any;
      }

      const dados = await query;

      console.log(
        `✅ [CONSELHO REALIZADOS] ${dados.length} registros encontrados`
      );

      res.json({
        success: true,
        dados: dados.map((d) => ({
          id: d.id,
          ano: d.ano,
          mes: d.mes,
          departamento: d.departamento,
          contasAReceber: parseFloat(d.contasAReceber || "0"),
          contasAPagar: parseFloat(d.contasAPagar || "0"),
          saldo: parseFloat(d.saldo || "0"),
        })),
      });
    } catch (error) {
      console.error("❌ [CONSELHO REALIZADOS] Erro ao buscar dados:", error);
      res.status(500).json({
        error: "Erro ao buscar dados realizados",
        details: error instanceof Error ? error.message : "Erro desconhecido",
      });
    }
  });

  // Inserir/atualizar dados realizados mensais
  app.post("/api/conselho/dados-realizados", async (req, res) => {
    try {
      const { ano, mes, departamento, contasAReceber, contasAPagar, saldo } =
        req.body;

      console.log(
        `💾 [CONSELHO REALIZADOS] Salvando dados - ${departamento} ${mes}/${ano}`
      );

      // Validação básica
      if (!ano || !mes || !departamento) {
        return res.status(400).json({
          error: "Campos obrigatórios: ano, mes, departamento",
        });
      }

      // Verificar se já existe registro para este período/departamento
      const existing = await db
        .select()
        .from(conselhoDadosRealizados)
        .where(
          and(
            eq(conselhoDadosRealizados.ano, ano),
            eq(conselhoDadosRealizados.mes, mes),
            eq(conselhoDadosRealizados.departamento, departamento)
          )
        )
        .limit(1);

      if (existing.length > 0) {
        // Atualizar registro existente
        await db
          .update(conselhoDadosRealizados)
          .set({
            contasAReceber: contasAReceber?.toString() || '0',
            contasAPagar: contasAPagar?.toString() || '0',
            saldo: saldo?.toString() || '0',
            updatedAt: new Date()
          })
          .where(eq(conselhoDadosRealizados.id, existing[0].id));

        console.log(
          `✅ [CONSELHO REALIZADOS] Registro atualizado: ${departamento} ${mes}/${ano}`
        );

        res.json({
          success: true,
          message: "Dados atualizados com sucesso",
          id: existing[0].id,
        });
      } else {
        // Inserir novo registro
        const result = await db
          .insert(conselhoDadosRealizados)
          .values({
            ano,
            mes,
            departamento,
            contasAReceber: contasAReceber?.toString() || "0",
            contasAPagar: contasAPagar?.toString() || "0",
            saldo: saldo?.toString() || "0",
          })
          .returning();

        console.log(
          `✅ [CONSELHO REALIZADOS] Novo registro criado: ${departamento} ${mes}/${ano}`
        );

        res.json({
          success: true,
          message: "Dados inseridos com sucesso",
          id: result[0].id,
        });
      }
    } catch (error) {
      console.error("❌ [CONSELHO REALIZADOS] Erro ao salvar dados:", error);
      res.status(500).json({
        error: "Erro ao salvar dados realizados",
        details: error instanceof Error ? error.message : "Erro desconhecido",
      });
    }
  });

