  // ================ RBAC SYSTEM ROUTES ================

  // Dashboard do Professor RBAC - Isolado
  app.get(
    "/api/professor/dashboard/:userId",
    requireAuth,
    requireProfessor,
    async (req, res) => {
      try {
        const userId = parseInt(req.params.userId);
        const user = (req as any).user;

        const access = ensureSelfAccess(user, userId, "dashboard");
        if (!access.allowed) {
          return res
            .status(access.error!.status)
            .json({ error: access.error!.message });
        }

        const vertente = (req.query.vertente as string) || 'pec';
        console.log(`✅ [RBAC PROFESSOR] Dashboard userId=${userId} vertente=${vertente}`);

        // Find professor record
        const userRow = await pool.query('SELECT email FROM users WHERE id = $1', [userId]);
        if (!userRow.rows.length) return res.json({ totalAlunos: 0, turmasAtivas: 0, horasAula: 0 });

        const programa = vertente === 'inclusao' ? 'inclusao_produtiva' : 'pec';
        const profRow = await pool.query(
          'SELECT id FROM professores WHERE email = $1 AND programa = $2 LIMIT 1',
          [userRow.rows[0].email, programa]
        );
        if (!profRow.rows.length) return res.json({ totalAlunos: 0, turmasAtivas: 0, horasAula: 0 });

        const profId = profRow.rows[0].id;
        const turmaTipo = vertente === 'inclusao' ? 'inclusao' : 'pec';
        const turmaRows = await pool.query(
          'SELECT turma_id FROM professor_turmas WHERE professor_id = $1 AND turma_tipo = $2',
          [profId, turmaTipo]
        );
        const turmaIds: number[] = turmaRows.rows.map((r: any) => r.turma_id);

        if (!turmaIds.length) return res.json({ totalAlunos: 0, turmasAtivas: 0, horasAula: 0 });

        let totalAlunos = 0;
        let turmasAtivas = 0;
        let horasAula = 0;

        let meusAlunos = 0;
        let alunosFormados = 0;

        if (vertente === 'pec') {
          const [meusAlunosRes, formadosRes, turmasRes, horasRes] = await Promise.all([
            pool.query('SELECT COUNT(DISTINCT student_cpf) FROM instance_enrollments WHERE activity_instance_id = ANY($1)', [turmaIds]),
            pool.query("SELECT COUNT(DISTINCT ie.student_cpf) FROM instance_enrollments ie JOIN activity_instances ai ON ie.activity_instance_id = ai.id WHERE ie.activity_instance_id = ANY($1) AND ai.status = 'encerrada'", [turmaIds]),
            pool.query("SELECT COUNT(*) FROM activity_instances WHERE id = ANY($1) AND status NOT IN ('encerrada','inativo')", [turmaIds]),
            pool.query(`
              SELECT COALESCE(SUM(
                (SELECT COUNT(*) FROM jsonb_array_elements(s.attendance) a
                  WHERE a->>'presente' = 'true' OR a->>'present' = 'true')
                * COALESCE(s.hours, 0)
              ), 0) as hora_aula
              FROM sessions s
              WHERE s.activity_instance_id = ANY($1)
            `, [turmaIds]),
          ]);
          meusAlunos = parseInt(meusAlunosRes.rows[0].count);
          alunosFormados = parseInt(formadosRes.rows[0].count);
          totalAlunos = meusAlunos;
          turmasAtivas = parseInt(turmasRes.rows[0].count);
          horasAula = Math.round(Number(horasRes.rows[0].hora_aula || 0));
        } else {
          const [meusAlunosRes, formadosRes, turmasRes] = await Promise.all([
            pool.query('SELECT COUNT(DISTINCT participante_id) FROM turmas_inclusao_participantes WHERE turma_id = ANY($1)', [turmaIds]),
            pool.query("SELECT COUNT(DISTINCT tip.participante_id) FROM turmas_inclusao_participantes tip JOIN turmas_inclusao ti ON tip.turma_id = ti.id WHERE tip.turma_id = ANY($1) AND ti.status = 'concluido'", [turmaIds]),
            pool.query("SELECT COUNT(*) FROM turmas_inclusao WHERE id = ANY($1) AND status NOT IN ('concluido','inativo')", [turmaIds]),
          ]);
          meusAlunos = parseInt(meusAlunosRes.rows[0].count);
          alunosFormados = parseInt(formadosRes.rows[0].count);
          totalAlunos = meusAlunos;
          turmasAtivas = parseInt(turmasRes.rows[0].count);
        }

        res.json({ totalAlunos, turmasAtivas, horasAula, meusAlunos, alunosFormados });
      } catch (error: any) {
        console.error("Error fetching professor dashboard:", error);
        res
          .status(500)
          .json({ error: "Failed to fetch dashboard: " + error.message });
      }
    }
  );


  // ================ MONITOR - PERFIL ================ 
  // GET /api/monitor/:userId/perfil - Buscar perfil do monitor (separado por vertente)
  app.get("/api/monitor/:userId/perfil", requireAuth, requireMonitor, async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);
      const user = (req as any).user;
      const vertente = req.query.vertente as string || 'pec';
      
      const access = ensureSelfAccess(user, userId, 'perfil');
      if (!access.allowed) {
        return res.status(access.error!.status).json({ error: access.error!.message });
      }
      
      // Buscar dados do perfil na tabela monitor_perfis para esta vertente usando SQL raw
      const perfilResult = await db.execute(sql`
        SELECT * FROM monitor_perfis 
        WHERE user_id = ${userId} AND vertente = ${vertente}
        LIMIT 1
      `);
      
      if (perfilResult.rows && perfilResult.rows.length > 0) {
        const perfil = perfilResult.rows[0] as any;
        return res.json({
          nome: perfil.nome,
          nome_completo: perfil.nome,
          email: perfil.email,
          telefone: perfil.telefone,
          area_atuacao: perfil.area_atuacao || (vertente === 'inclusao' ? 'Inclusão Produtiva' : 'PEC')
        });
      }
      
      // Se não tem perfil para esta vertente, buscar dados do usuário como fallback
      const userResult = await db
        .select()
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);
      
      if (!userResult || userResult.length === 0) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }
      
      const userData = userResult[0];
      res.json({
        nome: userData.nome,
        nome_completo: userData.nome,
        email: userData.email,
        telefone: userData.telefone,
        area_atuacao: vertente === 'inclusao' ? 'Inclusão Produtiva' : vertente === 'pec' ? 'PEC' : 'Monitoria Educacional'
      });
    } catch (error: any) {
      // Se a tabela não existe, retornar dados do usuário
      if (error.code === '42P01') {
        try {
          const userResult = await db.select().from(users).where(eq(users.id, parseInt(req.params.userId))).limit(1);
          if (userResult.length > 0) {
            const vertente = req.query.vertente as string;
            return res.json({
              nome: userResult[0].nome,
              nome_completo: userResult[0].nome,
              email: userResult[0].email,
              telefone: userResult[0].telefone,
              area_atuacao: vertente === 'inclusao' ? 'Inclusão Produtiva' : 'PEC'
            });
          }
        } catch (e) {}
      }
      console.error("❌ [MONITOR PERFIL] Erro ao buscar perfil:", error);
      res.status(500).json({ error: "Erro ao buscar perfil" });
    }
  });
  
  // PUT /api/monitor/:userId/perfil - Atualizar perfil do monitor (separado por vertente)
  app.put("/api/monitor/:userId/perfil", requireAuth, requireMonitor, async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);
      const user = (req as any).user;
      const { nome, email, telefone, area_atuacao, vertente } = req.body;
      
      const access = ensureSelfAccess(user, userId, 'perfil');
      if (!access.allowed) {
        return res.status(access.error!.status).json({ error: access.error!.message });
      }
      
      if (!vertente) {
        return res.status(400).json({ error: "Vertente não especificada" });
      }
      
      console.log(`🔄 [MONITOR PERFIL] Atualizando perfil do userId ${userId} na vertente ${vertente}`);
      
      // Criar tabela se não existir
      await db.execute(sql`
        CREATE TABLE IF NOT EXISTS monitor_perfis (
          id SERIAL PRIMARY KEY,
          user_id INTEGER NOT NULL,
          vertente TEXT NOT NULL,
          nome TEXT NOT NULL,
          email TEXT,
          telefone TEXT,
          area_atuacao TEXT,
          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          UNIQUE(user_id, vertente)
        )
      `);
      
      // Verificar se já existe perfil para esta vertente
      const perfilExistente = await db.execute(sql`
        SELECT id FROM monitor_perfis 
        WHERE user_id = ${userId} AND vertente = ${vertente}
        LIMIT 1
      `);
      
      if (perfilExistente.rows && perfilExistente.rows.length > 0) {
        // Atualizar perfil existente
        await db.execute(sql`
          UPDATE monitor_perfis 
          SET nome = ${nome}, email = ${email}, telefone = ${telefone}, area_atuacao = ${area_atuacao}, updated_at = NOW()
          WHERE user_id = ${userId} AND vertente = ${vertente}
        `);
        console.log(`✅ [MONITOR PERFIL] Perfil ${vertente} atualizado para userId ${userId}`);
      } else {
        // Criar novo perfil para esta vertente
        await db.execute(sql`
          INSERT INTO monitor_perfis (user_id, vertente, nome, email, telefone, area_atuacao)
          VALUES (${userId}, ${vertente}, ${nome}, ${email}, ${telefone}, ${area_atuacao})
        `);
        console.log(`✅ [MONITOR PERFIL] Novo perfil ${vertente} criado para userId ${userId}`);
      }
      
      res.json({ success: true, message: "Perfil atualizado com sucesso" });
    } catch (error: any) {
      console.error("❌ [MONITOR PERFIL] Erro ao atualizar perfil:", error);
      res.status(500).json({ error: "Erro ao atualizar perfil" });
    }
  });
