      // Permitir acesso para o próprio monitor, devs e admins
      const isOwner = atividade.monitorUserId === user.id;
      const isPrivileged = user.role && ['dev', 'admin', 'leo', 'monitor'].includes(user.role);
      console.log("[DELETE ATIVIDADE] user.id=" + user.id + ", user.role=" + user.role + ", atividade.monitorUserId=" + atividade.monitorUserId + ", isOwner=" + isOwner + ", isPrivileged=" + isPrivileged);
