 app.get(
  "/api/monitor/:monitorId/grupos/:grupoId/alunos",
  requireAuth,
  requireMonitor,
  async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId, 10);
      const grupoId = parseInt(req.params.grupoId, 10);
      const user = (req as any).user;

      const access = ensureSelfAccess(user, monitorId, "grupos-alunos");
      if (!access.allowed) return res.status(403).json({ error: "Acesso negado" });

      const role = String(user?.role || "").toLowerCase();

      const monitorRow = await db
        .select({ programa: monitores.programa })
        .from(monitores)
        .where(eq(monitores.id, monitorId))
        .limit(1);

      const pecInstance = await db.select({ id: activityInstances.id })
        .from(activityInstances)
        .where(eq(activityInstances.id, grupoId))
        .limit(1);
      
      if (pecInstance.length > 0) {
        // É uma turma PEC - buscar alunos de instanceEnrollments
        const matriculas = await db.select()
          .from(instanceEnrollments)
          .where(and(eq(instanceEnrollments.activity_instance_id, grupoId), eq(instanceEnrollments.active, true)));
        
        const cpfs = matriculas.map(m => m.student_cpf).filter(Boolean);
        
        if (cpfs.length === 0) {
          console.log(`[RBAC MONITOR] Monitor ${monitorId} listou 0 alunos do grupo PEC ${grupoId}`);
          return res.json([]);
        }
        
        const students = await db.select({
          cpf: aluno.cpf,
          nome: aluno.nome_completo,
          tipo: sql`'pec'`.as('tipo')
        })
        .from(aluno)
        .where(inArray(aluno.cpf, cpfs as string[]));
        
        const result = students.map(s => ({ ...s, id: s.cpf }));
        console.log(`[RBAC MONITOR] Monitor ${monitorId} listou ${result.length} alunos do grupo PEC ${grupoId}`);
        return res.json(result);
      }

      // Tenta buscar como Turma de Inclusão
      const turmaInclusao = await db.select().from(turmasInclusao)
        .where(eq(turmasInclusao.id, grupoId))
        .limit(1);
      
      if (turmaInclusao.length > 0) {
        // É uma turma de Inclusão - buscar participantes de participantesTurmas,
  alunoTurma,
  monitorPerfis
        const matriculas = await db.select({
          participanteId: participantesTurmas.participanteId,
          status: participantesTurmas.status
        })
          .from(participantesTurmas)
          .where(and(eq(participantesTurmas.turmaId, grupoId), eq(participantesTurmas.status, 'ativo')));
        
        const participanteIds = matriculas.map(m => m.participanteId);
        
        if (participanteIds.length === 0) {
          console.log(`[RBAC MONITOR] Monitor ${monitorId} listou 0 participantes da turma Inclusão ${grupoId}`);
          return res.json([]);
        }
        
        const students = await db.select({
          id: participantesInclusao.id,
          nome: participantesInclusao.nome,
          cpf: participantesInclusao.cpf,
          tipo: sql`'inclusao'`.as('tipo')
        })
        .from(participantesInclusao)
        .where(inArray(participantesInclusao.id, participanteIds));
        
        console.log(`[RBAC MONITOR] Monitor ${monitorId} listou ${students.length} participantes da turma Inclusão ${grupoId}`);
        return res.json(students);
      }

      // ✅ LEGACY/PEC: mantém sua lógica atual (monitorGrupos + monitorGrupoAlunos)
      const grupo = await db
        .select()
        .from(monitorGrupos)
        .where(and(eq(monitorGrupos.id, grupoId), eq(monitorGrupos.monitorUserId, monitorId)))
        .limit(1);

      if (!grupo.length) return res.status(404).json({ error: "Grupo não encontrado" });

      const alunosDoGrupo = await db
        .select()
        .from(monitorGrupoAlunos)
        .where(eq(monitorGrupoAlunos.grupoId, grupoId));

      const pecCpfs = alunosDoGrupo
        .filter((a) => a.participanteTipo === "pec" && a.participanteCpf)
        .map((a) => a.participanteCpf!);

      const inclusaoIds = alunosDoGrupo
        .filter((a) => a.participanteTipo === "inclusao" && a.participanteId)
        .map((a) => a.participanteId!);

      const students: any[] = [];

      if (pecCpfs.length > 0) {
        const pecStudents = await db
          .select({
            cpf: aluno.cpf,
            nome: aluno.nome_completo,
            tipo: sql`'pec'`.as("tipo"),
          })
          .from(aluno)
          .where(inArray(aluno.cpf, pecCpfs));

        students.push(...pecStudents.map((s) => ({ ...s, id: s.cpf })));
      }

      if (inclusaoIds.length > 0) {
        const inclusaoStudents = await db
          .select({
            id: participantesInclusao.id,
            nome: participantesInclusao.nome,
            cpf: participantesInclusao.cpf,
            tipo: sql`'inclusao'`.as("tipo"),
          })
          .from(participantesInclusao)
          .where(inArray(participantesInclusao.id, inclusaoIds));

        students.push(...inclusaoStudents);
      }

      console.log(`[RBAC MONITOR] Monitor ${monitorId} listou ${students.length} alunos do grupo ${grupoId}`);
      return res.json(students);
    } catch (error: any) {
      console.error("Error fetching grupo students:", error);
      return res.status(500).json({ error: "Failed to fetch students" });
    }
  }
);

  app.post("/api/monitor/:monitorId/grupos/:grupoId/alunos", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const grupoId = parseInt(req.params.grupoId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'grupos-alunos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      const { participanteId, participanteCpf, participanteTipo } = req.body;
      
      // Para Inclusão: usar turmasInclusao e participantesTurmas,
          alunoTurma,
          monitorPerfis
      if (participanteTipo === 'inclusao') {
        if (!participanteId) {
          return res.status(400).json({ error: 'participanteId é obrigatório para Inclusão' });
        }
        
        // Verificar se turma existe
        const turma = await db.select().from(turmasInclusao)
          .where(eq(turmasInclusao.id, grupoId))
          .limit(1);
        
        if (!turma.length) {
          return res.status(404).json({ error: 'Turma não encontrada' });
        }
        
        // Verificar se já existe
        const existing = await db.select().from(participantesTurmas)
          .where(and(
            eq(participantesTurmas.turmaId, grupoId),
            eq(participantesTurmas.participanteId, participanteId)
          ))
          .limit(1);
        
        if (existing.length) {
          return res.status(400).json({ error: 'Participante já está na turma' });
        }
        
        // Inserir na tabela participantesTurmas,
        alunoTurma,
        monitorPerfis
        const result =await db.insert(participantesTurmas).values({
          turmaId,
          participanteId,
          status: "ativo"
        })
        .returning();
        await syncParticipanteInclusaoStatus(participanteId);
        
        console.log(`[RBAC MONITOR] Participante ${participanteId} adicionado à turma inclusão ${grupoId}`);
        return res.json(result[0]);
      }
      
      // Para PEC: usar activityInstances e instanceEnrollments
      if (participanteTipo === 'pec') {
        if (!participanteCpf) {
          return res.status(400).json({ error: 'participanteCpf é obrigatório para PEC' });
        }
        
        // Verificar se turma PEC existe
        const turma = await db.select().from(activityInstances)
          .where(eq(activityInstances.id, grupoId))
          .limit(1);
        
        if (!turma.length) {
          return res.status(404).json({ error: 'Turma PEC não encontrada' });
        }
        
        // Verificar se já existe
        const existing = await db.select().from(instanceEnrollments)
          .where(and(
            eq(instanceEnrollments.activity_instance_id, grupoId),
            eq(instanceEnrollments.student_cpf, participanteCpf)
          ))
          .limit(1);
        
        if (existing.length) {
          return res.status(400).json({ error: 'Aluno já está na turma' });
        }
        
        // Inserir na tabela instanceEnrollments
        const result = await db.insert(instanceEnrollments)
          .values({
            activity_instance_id: grupoId,
            student_cpf: participanteCpf,
            active: true
          })
          .returning();
        
        console.log(`[RBAC MONITOR] Aluno ${participanteCpf} adicionado à turma PEC ${grupoId}`);
        return res.json(result[0]);
      }
      
      return res.status(400).json({ error: 'participanteTipo inválido' });
    } catch (error: any) {
      console.error("Error adding student to group:", error);
      res.status(500).json({ error: "Failed to add student to group" });
    }
  });
  // DELETE /api/monitor/:monitorId/grupos/:grupoId/alunos/:participanteIdentifier - Remove student from group
  // For PEC students, participanteIdentifier is CPF; for Inclusão, it's numeric ID
  // Use query param 'tipo' to specify 'pec' or 'inclusao'
  app.delete("/api/monitor/:monitorId/grupos/:grupoId/alunos/:participanteIdentifier", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const vertente = req.query.vertente as string | undefined; // 'pec' ou 'inclusao'
      const grupoId = parseInt(req.params.grupoId);
      const participanteIdentifier = req.params.participanteIdentifier;
      const tipo = req.query.tipo as string || 'inclusao'; // default to inclusao for backwards compatibility
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'grupos-alunos');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      // Verify group belongs to monitor
      const grupo = await db.select().from(monitorGrupos)
        .where(and(eq(monitorGrupos.id, grupoId), eq(monitorGrupos.monitorUserId, monitorId)))
        .limit(1);
      
      if (!grupo.length) {
        return res.status(404).json({ error: 'Grupo não encontrado' });
      }
      
      // Delete based on type
      if (tipo === 'pec') {
        await db.delete(monitorGrupoAlunos)
          .where(and(
            eq(monitorGrupoAlunos.grupoId, grupoId),
            eq(monitorGrupoAlunos.participanteCpf, participanteIdentifier)
          ));
      } else {
        const participanteId = parseInt(participanteIdentifier);
        await db.delete(monitorGrupoAlunos)
          .where(and(
            eq(monitorGrupoAlunos.grupoId, grupoId),
            eq(monitorGrupoAlunos.participanteId, participanteId)
          ));
      }
      
      // Update group alunos count
      await db.update(monitorGrupos)
        .set({
          alunos: sql`(SELECT COUNT(*) FROM monitor_grupo_alunos WHERE grupo_id = ${grupoId})` })
        .where(eq(monitorGrupos.id, grupoId));
      
      console.log(`[RBAC MONITOR] Aluno ${participanteIdentifier} (${tipo}) removido do grupo ${grupoId}`);
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error removing student from group:", error);
      res.status(500).json({ error: "Failed to remove student from group" });
    }
  });

  // POST /api/monitor/:monitorId/chamada - Create attendance record
  app.post("/api/monitor/:monitorId/chamada", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'chamada');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      const { grupoId, data, observacoes } = req.body;
      
      if (!grupoId || !data) {
        return res.status(400).json({ error: 'Selecione uma turma e uma data para registrar a chamada.' });
      }
      
      // Get the grupo to extract turmaId
      const grupo = await db.query.monitorGrupos.findFirst({
        where: and(
          eq(monitorGrupos.id, grupoId),
          eq(monitorGrupos.monitorUserId, monitorId)
        )
      });
      
      if (!grupo) {
        return res.status(404).json({ error: 'A turma selecionada não foi encontrada. Atualize a página e tente novamente.' });
      }
      
      if (!grupo.turmaId) {
        return res.status(400).json({ error: 'Esta turma ainda não está configurada corretamente. Entre em contato com o coordenador.' });
      }
      
      const validated = insertChamadaSchema.parse({
        turmaId: grupo.turmaId,
        data,
        professorId: monitorId,
        observacoes
      });
      
      const newChamada = await db.insert(chamada)
        .values(validated)
        .returning();
      
      console.log(`[RBAC MONITOR] Chamada criada por monitor ${monitorId} para grupo ${grupoId}`);
      res.json(newChamada[0]);
    } catch (error: any) {
      console.error("Error creating chamada:", error);
      const pgErr = formatPostgresError(error, 'chamada');
      res.status(pgErr.status).json({ error: pgErr.message });
    }
  });

  // POST /api/monitor/:monitorId/chamada/:chamadaId/presencas - Save attendance list
  app.post("/api/monitor/:monitorId/chamada/:chamadaId/presencas", requireAuth, requireMonitor, async (req, res) => {
    try {
      const monitorId = parseInt(req.params.monitorId);
      const chamadaId = parseInt(req.params.chamadaId);
      const user = (req as any).user;
      
      const access = ensureSelfAccess(user, monitorId, 'presencas');
      if (!access.allowed) {
        return res.status(403).json({ error: 'Acesso negado' });
      }
      
      const { presencas } = req.body;
      
      if (!Array.isArray(presencas)) {
        return res.status(400).json({ error: 'presencas deve ser um array' });
      }
      
      // Verify chamada belongs to this monitor
      const chamadaRecord = await db.query.chamada.findFirst({
        where: eq(chamada.id, chamadaId)
      });
      
      if (!chamadaRecord) {
        return res.status(404).json({ error: 'Chamada não encontrada' });
      }
      
      if (chamadaRecord.professorId !== monitorId) {
        return res.status(403).json({ error: 'Esta chamada não pertence a você' });
      }
      
      // Insert all presencas
      const insertedPresencas = [];
      for (const p of presencas) {
        const validated = insertChamadaAlunoSchema.parse({
          chamadaId,
          alunoCpf: p.alunoCpf,
          status: p.presente ? 'presente' : 'falta',
          observacoes: p.observacoes || null,
          justificativa: p.justificativa || null,
        });
        
        const inserted = await db.insert(chamadaAluno)
          .values(validated)
          .returning();
        
        insertedPresencas.push(inserted[0]);
      }
      
      console.log(`[RBAC MONITOR] Monitor ${monitorId} salvou ${insertedPresencas.length} presenças para chamada ${chamadaId}`);
      res.json({ success: true, count: insertedPresencas.length });
    } catch (error: any) {
      console.error("Error saving presencas:", error);
      res.status(500).json({ error: "Failed to save presencas" });
    }
  });

