  // Check-in diário com sistema de streak
  app.post("/api/users/:userId/checkin", async (req, res) => {
    try {
      // Não cachear
      res.set({
        "Cache-Control": "no-store, no-cache, must-revalidate, proxy-revalidate, max-age=0",
        Pragma: "no-cache",
        Expires: "0",
        "Surrogate-Control": "no-store",
      });

      const userIdParam = req.params.userId;
      const userId = Number(userIdParam);
      if (!Number.isFinite(userId)) {
        return res.status(400).json({ error: "userId inválido" });
      }

      // Busca usuário
      const [user] = await db
        .select({
          id: users.id,
          streak: users.diasConsecutivos, // int
          lastCheckin: users.ultimoCheckin, // datetime
        })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      // Helpers de data no fuso de SP (sem libs externas)
      const TZ = "America/Sao_Paulo";
      const fmtDia = (d: Date) =>
        d.toLocaleDateString("pt-BR", { timeZone: TZ });

      const agora = new Date();
      const hoje = fmtDia(agora);

      const last = user.lastCheckin ? new Date(user.lastCheckin) : null;
      const lastDia = last ? fmtDia(last) : null;

      // Já fez hoje?
      if (lastDia === hoje) {
        return res.status(400).json({ error: "Check-in já realizado hoje" });
      }

      // É ontem? (mantém streak)
      const ontemDate = new Date(agora);
      ontemDate.setDate(ontemDate.getDate() - 1);
      const ontem = fmtDia(ontemDate);

      let newStreak: number;
      if (lastDia === ontem) {
        newStreak = (user.streak ?? 0) + 1;
      } else {
        newStreak = 1;
      }

      // Dia no ciclo de 7
      const diaAtual = ((newStreak - 1) % 7) + 1;
      const gritosGanhos = diaAtual === 7 ? 1000 : 100; // 100 por dia, 1000 no 7º dia
      const isDay7 = diaAtual === 7;

        await db.transaction(async (tx) => {
          await tx
            .update(users)
            .set({
              diasConsecutivos: newStreak,
              ultimoCheckin: agora,
              gritosTotal: sql`COALESCE(${users.gritosTotal}, 0) + ${gritosGanhos}`,
            })
            .where(eq(users.id, userId));

          await tx.insert(gritosHistorico).values({
            userId,
            tipo: "checkin_diario",
            gritosGanhos,
            createdAt: agora, // 👈 CONFIRMA se esse campo existe no schema
          });
        });
      // pega total atualizado do campo CERTO
      const [tot] = await db
        .select({ gritosTotal: users.gritosTotal })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      // 🎯 AUTO-COMPLETAR MISSÕES DE CHECK-IN
      await checkAndCompleteCheckinMissions(userId, newStreak);
      return res.json({
        success: true,
        userId,
        gritosGanhos,
        diaAtual,
        isDay7,
        gritosTotal: tot?.gritosTotal ?? null,
        message: `Check-in realizado! +${gritosGanhos} Gritos${
          isDay7 ? " (Bônus do 7º dia!)" : ` (Dia ${diaAtual}/7)`
        }`,
      });
    } catch (error) {
      console.error("Error doing checkin:", error);
      return res.status(500).json({ error: "Erro interno do servidor" });
    }
  });


