  // 🔧 ADMIN: Listar e corrigir usuários com missões de check-in pendentes
  app.get("/api/admin/pending-checkin-missions", async (req, res) => {
    try {
      const missaoId = parseInt(req.query.missaoId as string) || 5;
      const diasNecessarios = parseInt(req.query.dias as string) || 3;
      
      const usuariosPendentes = await db.execute(sql`
        SELECT u.id, u.nome, u.dias_consecutivos, u.gritos_total
        FROM users u
        WHERE u.dias_consecutivos >= ${diasNecessarios}
        AND NOT EXISTS (
          SELECT 1 FROM missoes_concluidas mc
          WHERE mc.user_id = u.id AND mc.missao_id = ${missaoId}
        )
        ORDER BY u.dias_consecutivos DESC
      `);
      
      res.json({
        total: usuariosPendentes.rows.length,
        missaoId,
        diasNecessarios,
        usuarios: usuariosPendentes.rows
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

