        await db.insert(missoesConcluidas).values({ userId: user.id, missaoId, gritosRecebidos: missao.recompensaGritos || 150, fotoComprovante: null, evidenciaTexto: `Correção retroativa: ${user.dias_consecutivos} dias`, evidenceType: "automatico" as any });
        resultados.push({ userId: user.id, nome: user.nome, dias: user.dias_consecutivos });
