  // Salvar link de indicação informado pelo doador
  app.post("/api/indicacoes/salvar-link", requireAuth, async (req, res) => {
    try {
      const userId = (req as any).user?.id;
      const { link } = req.body;

      if (!userId) {
        return res.status(401).json({ error: "Não autenticado" });
      }

      if (!link) {
        return res.status(400).json({ error: "Link é obrigatório" });
      }

      // Verificar se já tem indicação registrada
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({ error: "Usuário não encontrado" });
      }

      if (user.ref_code_cadastro) {
        return res
          .status(400)
          .json({ error: "Você já tem um link de indicação registrado" });
      }

      // Extrair o ref code do link
      // Aceita: https://clubedogrito.institutoogrito.com.br/?ref=CODIGO ou apenas CODIGO
      let refCode = "";

      const urlMatch = link.match(/[?&]ref=([A-Z0-9-]+)/i);
      if (urlMatch) {
        refCode = urlMatch[1].toUpperCase();
      } else {
        // Se não tem formato de URL, assume que é só o código
        refCode = link.trim().toUpperCase();
      }

      // Validar formato do código
      if (!/^GRITO-[A-Z0-9]{6}$/.test(refCode)) {
        return res.status(400).json({
          error: "Código de indicação inválido. Use o formato GRITO-XXXXXX",
        });
      }

      // Verificar se o código existe
      const referrer = await storage.getUserByRefCode(refCode);

      if (!referrer) {
        return res
          .status(404)
          .json({ error: "Código de indicação não encontrado" });
      }

      // Não pode se auto-indicar
      if (referrer.id === userId) {
        return res.status(400).json({
          error: "Você não pode usar seu próprio código de indicação",
        });
      }

      // Salvar a indicação
      await storage.updateUserRefCodeCadastro(userId, refCode);

      console.log(
        `✅ [SALVAR-LINK] Usuário ${userId} foi indicado por ${referrer.nome} (${refCode})`
      );

      res.json({
        success: true,
        message: "Link de indicação salvo com sucesso!",
      });
    } catch (error) {
      console.error("❌ [SALVAR-LINK] Erro:", error);
      res.status(500).json({ error: "Erro ao salvar link de indicação" });
    }
  });

  // Salvar link de afiliado que o doador usou
  app.post(
    "/api/indicacoes/salvar-link-afiliado",
    requireAuth,
    async (req, res) => {
      try {
        const userId = (req as any).user?.id;
        const { link } = req.body;

        if (!userId) {
          return res.status(401).json({ error: "Não autenticado" });
        }

        if (!link) {
          return res.status(400).json({ error: "Link é obrigatório" });
        }

        // Verificar se já tem indicação registrada
        const user = await storage.getUser(userId);

        if (!user) {
          return res.status(404).json({ error: "Usuário não encontrado" });
        }

        // Extrair o slug do link
        // Aceita: https://clubedogrito.../cadastro?ref=slug ou apenas slug
        let refSlug = "";

        const urlMatch = link.match(/[?&]ref=([a-z0-9-]+)/i);
        if (urlMatch) {
          refSlug = urlMatch[1].toLowerCase();
        } else {
          refSlug = link.toLowerCase().trim();
        }

        if (!refSlug) {
          return res.status(400).json({
            error:
              "Link inválido. Não foi possível extrair o código de indicação",
          });
        }

        // Verificar se o slug existe
        const indicador = await storage.getUserByRefSlug(refSlug);

        if (!indicador) {
          return res.status(404).json({
            error: "Link de afiliado inválido. Código não encontrado",
          });
        }

        if (indicador.id === userId) {
          return res
            .status(400)
            .json({ error: "Você não pode usar seu próprio link de afiliado" });
        }

        // Salvar o slug
        await storage.updateUserRefSlugCadastro(userId, refSlug);

        console.log(
          `✅ [AFILIADO] Usuário ${userId} registrou link de afiliado: ${refSlug} (indicador: ${indicador.id})`
        );

        res.json({
          success: true,
          message: "Link de afiliado registrado com sucesso",
        });
      } catch (error) {
        console.error("❌ [SALVAR-AFILIADO] Erro:", error);
        res.status(500).json({ error: "Erro ao salvar link de afiliado" });
      }
    }
  );

