  // Buscar todos os benefícios
  app.get("/api/beneficios", async (req, res) => {
    try {
      const beneficios = await storage.getBeneficiosAtivos();
      console.log(
        `🎯 [API /api/beneficios] Retornando ${
          beneficios.length
        } benefícios (IDs: ${beneficios.map((b) => b.id).join(", ")})`
      );

      // Para cada benefício, buscar todas as imagens
      const beneficiosComImagens = await Promise.all(
        beneficios.map(async (beneficio) => {
          const imagens = await storage.getBeneficioImagensByBeneficio(
            beneficio.id
          );

          const imagemCard = imagens.find(
            (img) => (img.tipo ?? "").toLowerCase() === "card"
          );
          const imagemDetalhes = imagens.find(
            (img) => (img.tipo ?? "").toLowerCase() === "detalhes"
          );
          const primeiraImagem = imagemCard || imagens[0] || null;

          // sempre exponha 'imagem' apontando para a rota /api (compat com componentes legados)
          const imagemApi = imagemCard
            ? `/api/beneficios/${beneficio.id}/imagem?tipo=card`
            : primeiraImagem
            ? `/api/beneficios/${beneficio.id}/imagem`
            : null;

          return {
            ...beneficio,
            imagem: imagemApi, // 👈 força componentes antigos a usarem a rota certa
            imagemCardUrl: imagemCard
              ? `/api/beneficios/${beneficio.id}/imagem?tipo=card`
              : null,
            imagemDetalhesUrl: imagemDetalhes
              ? `/api/beneficios/${beneficio.id}/imagem?tipo=detalhes`
              : null,
            imagemUrl: primeiraImagem
              ? `/api/beneficios/${beneficio.id}/imagem`
              : null,
          };
        })
      );

      // Forçar no-cache para sempre pegar dados frescos
      res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate");
      res.setHeader("Pragma", "no-cache");
      res.setHeader("Expires", "0");
      res.json(beneficiosComImagens);
    } catch (error) {
      console.error("Error fetching beneficios:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

