  // Buscar benefícios (prêmios) elegíveis por plano + periodicidade
  // Regras oficiais:
  // ECO MENSAL: Apenas Combo Cineart
  // ECO TRIMESTRAL/ANUAL: Simples + Médios
  // VOZ MENSAL: Apenas Médios
  // VOZ TRIMESTRAL/ANUAL: Simples + Médios + Alguns Grandes
  // GRITO MENSAL: Médios + Grandes (sem iPhone)
  // GRITO TRIMESTRAL: Tudo menos iPhone
  // GRITO ANUAL: TODOS (incluindo iPhone)
  app.get(
    "/api/beneficios/plano/:plano/periodicidade/:periodicidade",
    async (req, res) => {
      try {
        const { plano, periodicidade } = req.params;
        console.log(
          `🎯 [API PRÊMIOS] Buscando prêmios para plano=${plano}, periodicidade=${periodicidade}`
        );

        // Buscar todos os benefícios ativos
        const todosBeneficios = await storage.getBeneficiosAtivos();

        // Filtrar por plano + periodicidade conforme regras oficiais
        console.log(
          `🎯 [FILTRO] Iniciando filtro: plano=${plano}, periodicidade=${periodicidade}, total=${todosBeneficios.length}`
        );
        const beneficiosFiltrados = todosBeneficios.filter((beneficio: any) => {
          // Normalizar plano e periodicidade para lowercase
          const userPlan = (plano || "").toLowerCase();
          const userPeriodicidade = (periodicidade || "").toLowerCase();

          // Normalizar arrays do benefício
          const planosBeneficio = (
            beneficio.planosDisponiveis ||
            beneficio.planos_disponiveis ||
            []
          ).map((p: string) => p.toLowerCase());
          const ciclosBeneficio = (
            beneficio.ciclosPagamento ||
            beneficio.ciclos_pagamento || ["mensal"]
          ).map((c: string) => c.toLowerCase());

          // REGRA 1: Platinum vê tudo, outros só veem prêmios onde seu plano está incluído
          const planAllowed =
            userPlan === "platinum" || planosBeneficio.includes(userPlan);
          if (!planAllowed) {
            return false;
          }

          // REGRA 2: A periodicidade deve estar nos ciclos de pagamento permitidos
          if (!ciclosBeneficio.includes(userPeriodicidade)) {
            return false;
          }

          return true;
        });

        console.log(
          `✅ [API PRÊMIOS] Encontrados ${beneficiosFiltrados.length} prêmios elegíveis`
        );

        // Para cada benefício, buscar todas as imagens
        const beneficiosComImagens = await Promise.all(
          beneficiosFiltrados.map(async (beneficio: any) => {
            const imagens = await storage.getBeneficioImagensByBeneficio(
              beneficio.id
            );

            // Separar imagens por tipo
            const imagemCard = imagens.find((img: any) => img.tipo === "card");
            const imagemDetalhes = imagens.find(
              (img: any) => img.tipo === "detalhes"
            );
            const primeiraImagem = imagemCard || imagens[0];

            return {
              ...beneficio,
              imagemCardUrl: imagemCard
                ? `/api/beneficios/${beneficio.id}/imagem?tipo=card`
                : null,
              imagemDetalhesUrl: imagemDetalhes
                ? `/api/beneficios/${beneficio.id}/imagem?tipo=detalhes`
                : null,
              imagemUrl: primeiraImagem
                ? `/api/beneficios/${beneficio.id}/imagem`
                : null,
            };
          })
        );

        res.json(beneficiosComImagens);
      } catch (error) {
        console.error(
          "Error fetching beneficios by plan and periodicity:",
          error
        );
        res.status(500).json({ error: "Erro interno do servidor" });
      }
    }
  );
  // Buscar benefício específico
  // Listar todos os ganhadores (público - para galeria) - DEVE VIR ANTES DE /api/beneficios/:id
  app.get("/api/beneficios/ganhadores", async (req, res) => {
    try {
      const result = await db
        .select({
          id: beneficioGanhadores.id,
          beneficioId: beneficioGanhadores.beneficioId,
          userId: beneficioGanhadores.userId,
          fotoUrl: beneficioGanhadores.fotoUrl,
          lancesTotais: beneficioGanhadores.lancesTotais,
          gritosTotais: beneficioGanhadores.gritosTotais,
          depoimento: beneficioGanhadores.depoimento,
          dataGanhou: beneficioGanhadores.dataGanhou,
          nomeUsuario: users.nome,
          beneficioTitulo: beneficios.titulo,
          beneficioImagem: beneficios.imagem,
          beneficioValor: beneficios.valorEstimado,
        })
        .from(beneficioGanhadores)
        .innerJoin(users, eq(beneficioGanhadores.userId, users.id))
        .innerJoin(
          beneficios,
          eq(beneficioGanhadores.beneficioId, beneficios.id)
        )
        .where(eq(beneficioGanhadores.visivel, true))
        .orderBy(desc(beneficioGanhadores.dataGanhou));

      res.json({ success: true, ganhadores: result });
    } catch (error: any) {
      console.error("Erro ao listar ganhadores:", error);
      res
        .status(500)
        .json({ success: false, message: "Erro ao listar ganhadores" });
    }
  });

