  // 🌍 ENDPOINT PARA SERVIR OBJETOS PÚBLICOS DO OBJECT STORAGE
  app.get("/public-objects/:filePath(*)", async (req, res) => {
    try {
      const filePath = req.params.filePath;
      const bucketId = process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID;

      if (!bucketId) {
        return res.status(500).json({ error: "Bucket não configurado" });
      }

      // Construir o caminho completo do objeto (public/ + filePath)
      const objectPath = `public/${filePath}`;
      const fullUrl = `https://storage.googleapis.com/${bucketId}/${objectPath}`;

      console.log(`📦 [PUBLIC-OBJECTS] Buscando: ${fullUrl}`);

      // Fazer fetch direto do GCS (os arquivos públicos devem estar acessíveis)
      const response = await fetch(fullUrl);

      if (!response.ok) {
        console.error(
          `❌ [PUBLIC-OBJECTS] Erro ${response.status} ao buscar ${fullUrl}`
        );

        // Retornar SVG placeholder ao invés de JSON quando houver erro
        const placeholderSvg = `<svg width="400" height="300" xmlns="http://www.w3.org/2000/svg">
          <rect width="100%" height="100%" fill="#1a1a1a"/>
          <text x="50%" y="45%" font-family="Arial" font-size="16" fill="#888" text-anchor="middle" dy=".3em">
            Imagem não disponível
          </text>
          <text x="50%" y="55%" font-family="Arial" font-size="12" fill="#666" text-anchor="middle" dy=".3em">
            Erro ${response.status}
          </text>
        </svg>`;

        res.set({
          'Content-Type': 'image/svg+xml',
          'Cache-Control': 'no-store, no-cache, must-revalidate',
          'Pragma': 'no-cache',
          'Expires': '0'
        });
        return res.send(placeholderSvg);
      }

      // Determinar Content-Type baseado na extensão
      const ext = filePath.split(".").pop()?.toLowerCase();
      const contentTypeMap: Record<string, string> = {
        jpg: "image/jpeg",
        jpeg: "image/jpeg",
        png: "image/png",
        gif: "image/gif",
        webp: "image/webp",
        pdf: "application/pdf",
        mp4: "video/mp4",
      };
      const contentType =
        contentTypeMap[ext || ""] || "application/octet-stream";

      // Servir o arquivo
      const arrayBuffer = await response.arrayBuffer();
      res.set({
        'Content-Type': contentType,
        'Cache-Control': 'public, max-age=31536000, immutable', // Cache por 1 ano
        'X-Served-From': 'public-object-storage'
      });
      res.send(Buffer.from(arrayBuffer));

      console.log(`✅ [PUBLIC-OBJECTS] Servido: ${filePath} (${contentType})`);
    } catch (error) {
      console.error(
        "❌ [PUBLIC-OBJECTS] Erro ao servir arquivo público:",
        error
      );
      res.status(500).json({ error: "Erro ao servir arquivo" });
    }
  });

  // Helper para gerar SVG placeholder
  const generatePlaceholderSVG = (
    width = 400,
    height = 300,
    message = "Imagem não disponível"
  ) => {
    return `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <rect width="100%" height="100%" fill="#1a1a1a"/>
      <text x="50%" y="50%" font-family="Arial" font-size="16" fill="#888" text-anchor="middle" dy=".3em">
        ${message}
      </text>
    </svg>`;
  };

  function resolveObjectKeyFromRow(row: any): string | null {
    const caminhoCompleto = row.caminhoCompleto ?? row.caminho_completo ?? null;
    const nomeArquivo = row.nomeArquivo ?? row.nome_arquivo ?? null;

    if (caminhoCompleto) {
      // se veio URL completa, transforma em chave "uploads/beneficios/arquivo.png"
      return caminhoCompleto.startsWith("http")
        ? extractFilePathFromUrl(caminhoCompleto)
        : caminhoCompleto;
    }
    if (nomeArquivo) {
      return `uploads/beneficios/${nomeArquivo}`;
    }
    return null;
  }

