  // Atualizar missão semanal (admin)
  app.put("/api/admin/missoes-semanais/:id", async (req, res) => {
    try {
      const missaoId = parseInt(req.params.id);

      // 🐛 DEBUG: Log dos dados recebidos do frontend
      console.log(
        `📝 [PUT MISSAO ${missaoId}] Dados recebidos:`,
        JSON.stringify(req.body, null, 2)
      );

      const {
        titulo,
        descricao,
        recompensaGritos,
        tipoMissao,
        imagemUrl,
        semanaInicio,
        semanaFim,
        ativo,
        nivelMinimo,
        limiteEnvios,
        reviewRequired,
        autoApprove,
        automatico,
        evidenceType,
        planoMinimo,
        habilitarLinkCompartilhamento,
        criteriosElegibilidade,
        dominiosPermitidos,
        distanciaMaxima,
        duracaoMaximaVideo,
        perguntasQuiz,
        percentualAcertoMinimo,
      } = req.body;

      // 🛡️ HELPERS PARA COERÇÃO DE TIPOS SEGURA - PRESERVA ZERO COMO VALOR VÁLIDO
      const safeParseInt = (value: any): number | undefined => {
        if (value === null || value === undefined || value === "")
          return undefined;
        const parsed = parseInt(String(value));
        return Number.isNaN(parsed) ? undefined : parsed;
      };

      const safeBooleanCoercion = (value: any): boolean | undefined => {
        if (value === null || value === undefined) return undefined;
        if (typeof value === "boolean") return value;
        if (typeof value === "string") {
          if (value === "true") return true;
          if (value === "false") return false;
        }
        return Boolean(value);
      };

      // 🛡️ SANITIZAÇÃO SELETIVA E SEGURA DOS CAMPOS PARA O BANCO
      const updateFields: any = {};

      // Campos básicos - APENAS incluir se fornecidos explicitamente
      if (titulo !== undefined) updateFields.titulo = titulo;
      if (descricao !== undefined) updateFields.descricao = descricao;
      if (recompensaGritos !== undefined) {
        const recompensa = safeParseInt(recompensaGritos);
        if (recompensa !== undefined)
          updateFields.recompensaGritos = recompensa;
      }
      if (tipoMissao !== undefined) updateFields.tipoMissao = tipoMissao;
      if (semanaInicio !== undefined) updateFields.semanaInicio = semanaInicio;
      if (semanaFim !== undefined) updateFields.semanaFim = semanaFim;
      if (ativo !== undefined) {
        const ativoValue = safeBooleanCoercion(ativo);
        if (ativoValue !== undefined) updateFields.ativo = ativoValue;
      }

      // Campos do sistema avançado
      if (automatico !== undefined) {
        const automaticoValue = safeBooleanCoercion(automatico);
        if (automaticoValue !== undefined)
          updateFields.automatico = automaticoValue;
      }
      if (evidenceType !== undefined) updateFields.evidenceType = evidenceType;
      if (imagemUrl !== undefined) updateFields.imagemUrl = imagemUrl;

      // Quantidade de amigos para missões de referral
      if (req.body.quantidadeAmigos !== undefined) {
        const qtd = safeParseInt(req.body.quantidadeAmigos);
        if (qtd !== undefined) updateFields.quantidadeAmigos = qtd;
      }

      // Dias necessários para missões de check-in consecutivo
      if (req.body.diasNecessarios !== undefined) {
        const dias = safeParseInt(req.body.diasNecessarios);
        if (dias !== undefined) updateFields.diasNecessarios = dias;
      }

      // Configurações de elegibilidade
      if (planoMinimo !== undefined) updateFields.planoMinimo = planoMinimo;
      if (nivelMinimo !== undefined) {
        const nivel = safeParseInt(nivelMinimo);
        if (nivel !== undefined) updateFields.nivelMinimo = nivel;
      }
      if (limiteEnvios !== undefined) {
        const limite = safeParseInt(limiteEnvios);
        if (limite !== undefined) updateFields.limiteEnvios = limite;
      }

      // Configurações de aprovação
      if (reviewRequired !== undefined) {
        const reviewValue = safeBooleanCoercion(reviewRequired);
        if (reviewValue !== undefined)
          updateFields.reviewRequired = reviewValue;
      }
      if (autoApprove !== undefined) {
        const autoApproveValue = safeBooleanCoercion(autoApprove);
        if (autoApproveValue !== undefined)
          updateFields.autoApprove = autoApproveValue;
      }
      if (habilitarLinkCompartilhamento !== undefined) {
        const habilitarValue = safeBooleanCoercion(
          habilitarLinkCompartilhamento
        );
        if (habilitarValue !== undefined)
          updateFields.habilitarLinkCompartilhamento = habilitarValue;
      }

      // Configurações específicas por tipo de evidência
      if (criteriosElegibilidade !== undefined)
        updateFields.criteriosElegibilidade = criteriosElegibilidade;
      if (dominiosPermitidos !== undefined)
        updateFields.dominiosPermitidos = dominiosPermitidos;
      if (distanciaMaxima !== undefined) {
        const distancia = safeParseInt(distanciaMaxima);
        if (distancia !== undefined) updateFields.distanciaMaxima = distancia;
      }
      if (duracaoMaximaVideo !== undefined) {
        const duracao = safeParseInt(duracaoMaximaVideo);
        if (duracao !== undefined) updateFields.duracaoMaximaVideo = duracao;
      }
      if (perguntasQuiz !== undefined)
        updateFields.perguntasQuiz = perguntasQuiz;
      if (percentualAcertoMinimo !== undefined) {
        const percentual = safeParseInt(percentualAcertoMinimo);
        if (percentual !== undefined)
          updateFields.percentualAcertoMinimo = percentual;
      }

      const [missaoAtualizada] = await db
        .update(missoesSemanais)
        .set(updateFields)
        .where(eq(missoesSemanais.id, missaoId))
        .returning();

      if (!missaoAtualizada) {
        return res.status(404).json({ error: "Missão não encontrada" });
      }

      res.json(missaoAtualizada);
    } catch (error) {
      console.error("❌ [ERROR] Error updating mission:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // Deletar missão semanal (admin)
  app.delete("/api/admin/missoes-semanais/:id", async (req, res) => {
    try {
      const missaoId = parseInt(req.params.id);

      // Primeiro, deletar transações relacionadas (pagamentos de missão)
      await db
        .delete(missaoTransacoes)
        .where(eq(missaoTransacoes.missaoId, missaoId));

      // Terceiro, deletar referrals relacionados (missões de indicação)
      await db.delete(referrals).where(eq(referrals.missaoId, missaoId));

      // Quarto, deletar conclusões relacionadas
      await db
        .delete(missoesConcluidas)
        .where(eq(missoesConcluidas.missaoId, missaoId));

      // Depois deletar a missão
      const [missaoDeletada] = await db
        .delete(missoesSemanais)
        .where(eq(missoesSemanais.id, missaoId))
        .returning();

      if (!missaoDeletada) {
        return res.status(404).json({ error: "Missão não encontrada" });
      }

      res.json({ success: true, message: "Missão deletada com sucesso" });
    } catch (error) {
      console.error("Error deleting mission:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // ===== REGULARIZAR SUBSCRIPTIONS COM PRODUTO ERRADO =====
  // Corrigir subscriptions que foram criadas com "Doação Clube do Grito" em vez do plano correto
  app.post("/api/admin/regularize-subscriptions", async (req, res) => {
    try {
      console.log(
        "🔧 [REGULARIZE] Iniciando regularização de subscriptions..."
      );

      if (!stripe) {
        return res.status(500).json({ error: "Stripe não configurado" });
      }

      // Buscar produto "Doação Clube do Grito"
      const products = await stripe.products.list({ active: true, limit: 100 });
      const donationProduct = products.data.find(
        (p) =>
          p.name === "Doação Clube do Grito" || p.metadata?.type === "donation"
      );

      if (!donationProduct) {
        return res.json({
          success: true,
          message:
            'Produto "Doação Clube do Grito" não encontrado - nada a regularizar',
          regularizados: 0,
        });
      }

      console.log(
        `📦 [REGULARIZE] Produto de doação encontrado: ${donationProduct.id}`
      );

      // Buscar subscriptions ativas
      const allSubs = await stripe.subscriptions.list({
        status: "active",
        limit: 100,
        expand: ["data.customer", "data.items.data.price"],
      });

      const subsParaCorrigir = allSubs.data.filter((sub) => {
        const productId = sub.items.data[0]?.price?.product;
        return productId === donationProduct.id;
      });

      console.log(
        `🔍 [REGULARIZE] ${subsParaCorrigir.length} subscriptions com produto "Doação" encontradas`
      );

      const resultados: any[] = [];

      for (const sub of subsParaCorrigir) {
        try {
          const customer = sub.customer as any;
          const priceItem = sub.items.data[0];
          const valorTotal = priceItem?.price?.unit_amount || 0;
          const interval = priceItem?.price?.recurring?.interval || "month";
          const intervalCount =
            priceItem?.price?.recurring?.interval_count || 1;

          // Calcular valor mensal
          let valorMensal = valorTotal / 100;
          if (interval === "month" && intervalCount > 1) {
            valorMensal = valorTotal / 100 / intervalCount;
          } else if (interval === "year") {
            valorMensal = valorTotal / 100 / 12;
          }

          // Determinar plano correto baseado no valor
          let planoCorreto = "platinum";
          if (valorMensal < 15) planoCorreto = "eco";
          else if (valorMensal < 25) planoCorreto = "voz";
          else if (valorMensal < 35) planoCorreto = "grito";

          // Determinar periodicidade
          let periodicidade = "mensal";
          if (interval === "year") periodicidade = "anual";
          else if (intervalCount === 3) periodicidade = "trimestral";
          else if (intervalCount === 6) periodicidade = "semestral";

          // Atualizar metadata da subscription
          await stripe.subscriptions.update(sub.id, {
            metadata: {
              ...sub.metadata,
              plan: planoCorreto,
              tier: planoCorreto,
              periodicity: periodicidade,
              periodicityLabel:
                periodicidade.charAt(0).toUpperCase() + periodicidade.slice(1),
              regularized: "true",
              regularizedAt: new Date().toISOString(),
              valorMensalCalculado: valorMensal.toFixed(2),
              flowVersion: "3.0-regularized",
            },
          });

          resultados.push({
            subscriptionId: sub.id,
            customer: customer?.name || customer?.email || "Desconhecido",
            valorTotal: valorTotal / 100,
            valorMensal: valorMensal,
            planoAnterior: sub.metadata?.plan || "indefinido",
            planoCorreto: planoCorreto,
            periodicidade: periodicidade,
            status: "regularizado",
          });

          console.log(
            `✅ [REGULARIZE] ${sub.id}: ${customer?.name} -> ${planoCorreto} (${periodicidade})`
          );
        } catch (error: any) {
          console.error(
            `❌ [REGULARIZE] Erro ao regularizar ${sub.id}:`,
            error.message
          );
          resultados.push({
            subscriptionId: sub.id,
            status: "erro",
            erro: error.message,
          });
        }
      }

      res.json({
        success: true,
        message: `${
          resultados.filter((r) => r.status === "regularizado").length
        } subscriptions regularizadas`,
        totalAnalisadas: subsParaCorrigir.length,
        regularizados: resultados.filter((r) => r.status === "regularizado")
          .length,
        erros: resultados.filter((r) => r.status === "erro").length,
        detalhes: resultados,
      });
    } catch (error: any) {
      console.error("❌ [REGULARIZE] Erro geral:", error);
      res.status(500).json({
        success: false,
        error: "Erro ao regularizar subscriptions",
        message: error.message,
      });
    }
  });

