  // 🔗 NOVA ROTA: Buscar missões de referral com informações completas
  app.get("/api/referrals/missions/:userId", async (req, res) => {
    try {
      const userId = parseInt(req.params.userId);

      if (isNaN(userId)) {
        return res.status(400).json({ error: "ID de usuário inválido" });
      }

      // Buscar missões que permitem link de compartilhamento
      const missoesReferral = await db
        .select()
        .from(missoesSemanais)
        .where(
          and(
            eq(missoesSemanais.ativo, true),
            eq(missoesSemanais.habilitarLinkCompartilhamento, true)
          )
        )
        .orderBy(desc(missoesSemanais.recompensaGritos));

      // Para cada missão, buscar o progresso do usuário
      const missoesComProgresso = await Promise.all(
        missoesReferral.map(async (missao) => {
          // Verificar se já foi concluída
          const jaConcluida = await db
            .select()
            .from(missoesConcluidas)
            .where(
              and(
                eq(missoesConcluidas.userId, userId),
                eq(missoesConcluidas.missaoId, missao.id)
              )
            )
            .limit(1);

          // Contar referrals completos
          const referralsCompletos = await db
            .select()
            .from(referrals)
            .where(
              and(
                eq(referrals.referrerUserId, userId),
                eq(referrals.missaoId, missao.id),
                eq(referrals.status, "completo")
              )
            );

          const quantidadeNecessaria = missao.quantidadeAmigos || 1;
          const cadastrosCompletos = referralsCompletos.length;
          const progresso = Math.min(
            (cadastrosCompletos / quantidadeNecessaria) * 100,
            100
          );

          return {
            id: missao.id,
            titulo: missao.titulo,
            descricao: missao.descricao,
            recompensaGritos: missao.recompensaGritos,
            quantidadeAmigos: quantidadeNecessaria,
            tipoMissao: missao.tipoMissao,
            imagemUrl: missao.imagemUrl,

            // Progresso do usuário
            concluida: jaConcluida.length > 0,
            concluidaEm: jaConcluida[0]?.createdAt || null,
            cadastrosCompletos,
            progresso: parseFloat(progresso.toFixed(1)),
            podeCompletar:
              cadastrosCompletos >= quantidadeNecessaria &&
              jaConcluida.length === 0,
            // Links dos referrals para esta missão
            referrals: referralsCompletos.map((r) => ({
              id: r.id,
              linkConvite: r.linkConvite,
              codigoConvite: r.codigoConvite,
              completadoEm: r.completadoEm,
              referredUserId: r.referredUserId,
            })),
          };
        })
      );

      console.log(
        `📊 [REFERRAL MISSIONS] Usuário ${userId}: ${missoesComProgresso.length} missões de referral encontradas`
      );

      res.json({
        success: true,
        missoes: missoesComProgresso,
        summary: {
          totalMissoes: missoesComProgresso.length,
          concluidas: missoesComProgresso.filter((m) => m.concluida).length,
          emProgresso: missoesComProgresso.filter(
            (m) => !m.concluida && m.cadastrosCompletos > 0
          ).length,
          disponiveis: missoesComProgresso.filter(
            (m) => !m.concluida && m.cadastrosCompletos === 0
          ).length,
        },
      });
    } catch (error) {
      console.error("Erro ao buscar missões de referral:", error);
      res.status(500).json({ error: "Erro interno do servidor" });
    }
  });

  // ================ APIS DE INDICAÇÃO NO PERFIL ================

  // API para aplicar código de referral (usuário indica que foi convidado)
  app.post("/api/aplicar-codigo-referral", async (req, res) => {
    try {
      const { userId, codigoReferral: codigoRaw } = req.body;

      // Extrair código do link se for URL completa
      let codigoReferral = codigoRaw.trim();

      // Se contém "ref=" ou "?ref=", extrair o código
      if (codigoReferral.includes("ref=")) {
        const match = codigoReferral.match(/[?&]ref=([^&]+)/);
        if (match) {
          codigoReferral = decodeURIComponent(match[1]);
          console.log(
            `🔗 [APLICAR REFERRAL] Código extraído do link: ${codigoReferral}`
          );
        }
      }

      // Se é uma URL mas não tem ref=, tentar extrair última parte do path
      if (codigoReferral.includes("://") && !codigoReferral.includes("ref=")) {
        try {
          const url = new URL(codigoReferral);
          const pathParts = url.pathname.split("/").filter(Boolean);
          if (pathParts.length > 0) {
            codigoReferral = pathParts[pathParts.length - 1];
            console.log(
              `🔗 [APLICAR REFERRAL] Código extraído do path: ${codigoReferral}`
            );
          }
        } catch (e) {
          // Não é URL válida, usar como está
        }
      }

      if (!userId || !codigoRaw) {
        return res
          .status(400)
          .json({ error: "userId e codigoReferral são obrigatórios" });
      }

      console.log(
        `🔗 [APLICAR REFERRAL] Usuário ${userId} tentando aplicar código: ${codigoReferral}`
      );

      // Verificar se o usuário já tem um código aplicado em referrals
      const jaIndicadoReferral = await db
        .select()
        .from(referrals)
        .where(eq(referrals.referredUserId, parseInt(userId)))
        .limit(1);

      // Também verificar na tabela indicacoes
      const jaIndicadoIndicacoes = await db
        .select()
        .from(indicacoes)
        .where(eq(indicacoes.indicadoId, parseInt(userId)))
        .limit(1);

      if (jaIndicadoReferral[0] || jaIndicadoIndicacoes[0]) {
        console.log(
          `⚠️ [APLICAR REFERRAL] Usuário ${userId} já foi indicado antes`
        );
        return res
          .status(400)
          .json({ error: "Você já possui um código de indicação aplicado" });
      }

      // PRIMEIRO: Tentar buscar na tabela referrals (códigos tipo REF_xxx das missões)
      const referralData = await db
        .select()
        .from(referrals)
        .where(eq(referrals.codigoConvite, codigoReferral))
        .limit(1);

      if (referralData[0]) {
        // É um código de missão (referral)
        const referral = referralData[0];

        // Verificar se o referral já foi usado
        if (referral.referredUserId) {
          console.log(
            `⚠️ [APLICAR REFERRAL] Código já foi usado por outro usuário`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação já foi utilizado" });
        }

        // Verificar se não está expirado
        if (referral.expiradoEm && new Date(referral.expiradoEm) < new Date()) {
          console.log(
            `⏰ [APLICAR REFERRAL] Código expirado: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação expirou" });
        }

        // Verificar se o usuário não está tentando usar seu próprio código
        if (referral.referrerUserId === parseInt(userId)) {
          console.log(
            `🚫 [APLICAR REFERRAL] Usuário tentando usar próprio código`
          );
          return res.status(400).json({
            error: "Você não pode usar seu próprio código de indicação",
          });
        }

        // Atualizar o referral com o usuário indicado
        await db
          .update(referrals)
          .set({
            referredUserId: parseInt(userId),
            status: "cadastrou",
            cadastrouEm: new Date(),
          })
          .where(eq(referrals.id, referral.id));

        // Buscar nome de quem indicou
        const indicador = await db
          .select({ nome: users.nome, sobrenome: users.sobrenome })
          .from(users)
          .where(eq(users.id, referral.referrerUserId))
          .limit(1);

        const nomeIndicador = indicador[0]
          ? `${indicador[0].nome || ""} ${
              indicador[0].sobrenome || ""
            }`.trim() || "Um amigo"
          : "Um amigo";

        console.log(
          `✅ [APLICAR REFERRAL] Código de missão aplicado! Usuário ${userId} foi indicado por ${referral.referrerUserId}`
        );

        return res.json({
          success: true,
          message: `Parabéns! Você foi indicado por ${nomeIndicador}`,
          indicadorNome: nomeIndicador,
          indicadorId: referral.referrerUserId,
          tipo: "missao",
        });
      }

      // SEGUNDO: Tentar buscar na tabela marketing_links (códigos de campanhas de marketing)
      const marketingLinkData = await db
        .select()
        .from(marketingLinks)
        .where(eq(marketingLinks.code, codigoReferral))
        .limit(1);

      if (marketingLinkData[0]) {
        // É um código de marketing
        const marketingLink = marketingLinkData[0];

        // Verificar se está ativo
        if (!marketingLink.isActive) {
          console.log(
            `❌ [APLICAR REFERRAL] Link de marketing inativo: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação não está mais ativo" });
        }

        // Verificar se não está expirado
        if (
          marketingLink.expiresAt &&
          new Date(marketingLink.expiresAt) < new Date()
        ) {
          console.log(
            `⏰ [APLICAR REFERRAL] Link de marketing expirado: ${codigoReferral}`
          );
          return res
            .status(400)
            .json({ error: "Este código de indicação expirou" });
        }

        // Verificar se o usuário não está tentando usar seu próprio código
        if (marketingLink.rewardToUserId === parseInt(userId)) {
          console.log(
            `🚫 [APLICAR REFERRAL] Usuário tentando usar próprio código de marketing`
          );
          return res.status(400).json({
            error: "Você não pode usar seu próprio código de indicação",
          });
        }

        // Registrar a indicação na tabela indicacoes (se tiver rewardToUserId)
        if (marketingLink.rewardToUserId) {
          const validade = new Date();
          validade.setDate(validade.getDate() + 30);

          await db.insert(indicacoes).values({
            indicouId: marketingLink.rewardToUserId,
            indicadoId: parseInt(userId),
            refCode: codigoReferral,
            status: "CONFIRMADA",
            criadaEm: new Date(),
            confirmadaEm: new Date(),
            validade: validade,
          });
        }

        // Buscar nome de quem criou o link (se tiver rewardToUserId)
        let nomeIndicador = "Campanha do Clube do Grito";
        if (marketingLink.rewardToUserId) {
          const indicador = await db
            .select({ nome: users.nome, sobrenome: users.sobrenome })
            .from(users)
            .where(eq(users.id, marketingLink.rewardToUserId))
            .limit(1);

          if (indicador[0]) {
            nomeIndicador =
              `${indicador[0].nome || ""} ${
                indicador[0].sobrenome || ""
              }`.trim() || "Um amigo";
          }
        }

        console.log(
          `✅ [APLICAR REFERRAL] Código de marketing aplicado! Usuário ${userId} veio do link ${marketingLink.id}`
        );

        return res.json({
          success: true,
          message: `Parabéns! Você foi indicado por ${nomeIndicador}`,
          indicadorNome: nomeIndicador,
          indicadorId: marketingLink.rewardToUserId || null,
          tipo: "marketing",
        });
      }

      // Se não encontrou em nenhuma das duas tabelas
      console.log(
        `❌ [APLICAR REFERRAL] Código não encontrado em nenhuma tabela: ${codigoReferral}`
      );
      return res
        .status(404)
        .json({ error: "Código de indicação não encontrado" });
    } catch (error) {
      console.error("❌ [APLICAR REFERRAL] Erro:", error);
      res.status(500).json({ error: "Erro ao aplicar código de indicação" });
    }
  });

