  // ===== BUSCAR TODOS OS PAGAMENTOS DE INGRESSOS =====
  app.get("/api/ingresso/pagamentos", async (req, res) => {
    try {
      console.log(
        "📊 [INGRESSO DASHBOARD] Buscando pagamentos de ingressos do banco..."
      );

      // Buscar ingressos do banco de dados local
      const ingressosDb = await db
        .select()
        .from(ingressos)
        .orderBy(desc(ingressos.criadoEm));

      console.log(
        `📋 [DB] Total de ${ingressosDb.length} ingressos encontrados no banco`
      );

      // Formatar ingressos
      const pagamentosFormatados = ingressosDb.map((ingresso) => {
        const statusMap: { [key: string]: string } = {
          confirmado: "succeeded",
          aprovado: "succeeded",
          pendente: "processing",
          cancelado: "canceled",
          ativo: "succeeded",
        };

        const statusDetalhado: { [key: string]: string } = {
          confirmado: "Pagamento confirmado com sucesso",
          aprovado: "Pagamento confirmado com sucesso",
          pendente: "Pagamento em processamento",
          cancelado: "Pagamento cancelado",
          ativo: "Ingresso ativo",
        };

        const gatewayLabel =
          ingresso.gateway === "stripe"
            ? "Cartão (Stripe)"
            : ingresso.gateway === "rede"
            ? "Cartão (Rede)"
            : ingresso.gateway === "pix"
            ? "PIX"
            : ingresso.gateway === "cota_empresa"
            ? "Cota Empresa"
            : "Outro";

        const status = statusMap[ingresso.status || "pendente"] || "processing";

        return {
          id: ingresso.id.toString(),
          numero: ingresso.numero,
          nome: ingresso.nomeComprador || "N/A",
          telefone: ingresso.telefoneComprador || "N/A",
          email: ingresso.emailComprador || "N/A",
          metodo: gatewayLabel,
          gateway: ingresso.gateway,
          quantidade: 1,
          valor: ingresso.valorPago,
          valorFormatado: `R$ ${(ingresso.valorPago / 100)
            .toFixed(2)
            .replace(".", ",")}`,
          data: ingresso.criadoEm ? ingresso.criadoEm.toISOString() : null,
          status: status,
          statusOriginal: ingresso.status,
          statusDetalhado:
            statusDetalhado[ingresso.status || "pendente"] || ingresso.status,
          resumoAtividade: [
            `${ingresso.criadoEm?.toLocaleString("pt-BR")}: Ingresso criado`,
            `${ingresso.criadoEm?.toLocaleString("pt-BR")}: ${
              statusDetalhado[ingresso.status || "pendente"] || "Processado"
            }`,
          ],
          temReembolso: false,
          valorReembolsado: 0,
          reembolsoCompleto: false,
          statusLabel:
            status === "succeeded"
              ? "Pago"
              : status === "processing"
              ? "Processando"
              : status === "canceled"
              ? "Cancelado"
              : "Outros",
        };
      });

      // Estatísticas
      const stats = {
        total: pagamentosFormatados.length,
        succeeded: pagamentosFormatados.filter((p) => p.status === "succeeded")
          .length,
        failed: pagamentosFormatados.filter((p) => p.status === "canceled")
          .length,
        refunded: 0,
        processing: pagamentosFormatados.filter(
          (p) => p.status === "processing"
        ).length,
        aguardandoPagamento: 0,
        requiresAction: 0,
      };

      res.json(pagamentosFormatados);
    } catch (error) {
      console.error(
        "❌ [INGRESSO DASHBOARD] Erro ao buscar pagamentos:",
        error
      );
      res.status(500).json({ error: "Erro ao buscar pagamentos" });
    }
  });

