  // Criar novo programa
  app.post("/api/programas-inclusao", async (req, res) => {
    try {
      const coordenadorId = req.user?.id;

      const vagasRaw = req.body.numeroVagas ?? req.body.vagas; // aceita ambos
      const vagasNum =
        vagasRaw === "" || vagasRaw === null || vagasRaw === undefined
          ? null
          : Number(vagasRaw);

      const numeroVagas =
        vagasNum !== null && Number.isFinite(vagasNum) && vagasNum > 0
          ? Math.floor(vagasNum)
          : null; // ✅ permite programa "guarda-chuva" sem vagas

      const programaData = {
        ...req.body,
        coordenadorId,
        numeroVagas, // ✅ null quando não tiver
        vagasOcupadas: 0,
        taxaOcupacao: 0,
      };
      
      // Se tem data de conclusão no passado, força status para concluído
      if (programaData.dataFim) {
        const dataFim = new Date(programaData.dataFim);
        const hoje = new Date();
        hoje.setHours(0, 0, 0, 0);
        
        if (dataFim < hoje) {
          programaData.status = 'concluido';
          console.log(`📅 [PROGRAMAS] Data de conclusão (${programaData.dataFim}) já passou, criando com status concluído`);
        }
      }

      const programa = await storage.createPrograma(programaData);
      res.status(201).json(programa);
    } catch (error: any) {
      console.error("Erro ao criar programa:", error);
      res.status(500).json({ error: "Erro ao criar programa" });
    }
  });

