  app.delete("/api/documentos/:id", requireAuth, async (req, res) => {
    try {
      const documentoId = parseInt(req.params.id);
      
      // Buscar documento para pegar a URL
      const [doc] = await db.select().from(documentosParticipante)
        .where(eq(documentosParticipante.id, documentoId));
      
      if (!doc) {
        return res.status(404).json({ error: "Documento não encontrado" });
      }
      
      // Tentar excluir do GCS
      try {
        const filePath = extractFilePathFromUrl(doc.urlArquivo);
        if (filePath) {
          await deleteObject(filePath);
        }
      } catch (gcsError) {
        console.warn("Aviso: não foi possível excluir arquivo do GCS:", gcsError);
      }
      
      // Excluir do banco
      await db.delete(documentosParticipante)
        .where(eq(documentosParticipante.id, documentoId));
      
      res.json({ success: true });
    } catch (error: any) {
      console.error("Erro ao excluir documento:", error);
      res.status(500).json({ error: "Erro ao excluir documento" });
    }
  });


